/**
 * Daemon Lifecycle Parameter Schemas
 *
 * Daemon lifecycle and supervisor related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/daemon
 */
import { z } from "zod";
// =============================================================================
// Daemon Lifecycle Params
// =============================================================================
/**
 * Daemon ping parameters (empty)
 */
export const DaemonPingParams = z.object({});
/**
 * Daemon status parameters (empty)
 */
export const DaemonStatusParams = z.object({});
/**
 * Daemon shutdown parameters (empty)
 */
export const DaemonShutdownParams = z.object({});
/**
 * Daemon reload parameters (empty)
 */
export const DaemonReloadParams = z.object({});
// =============================================================================
// Supervisor Params
// =============================================================================
/**
 * Supervisor register parameters
 */
export const SupervisorRegisterParams = z.object({
    /** Absolute path to workspace root */
    workspace: z.string().min(1),
    /** Component type */
    type: z.enum(["mcp-stdio", "mcp-http"]),
    /** Process ID of the component */
    pid: z.number().int().positive(),
    /** Restart strategy */
    restartStrategy: z.enum(["one-for-one", "one-for-all"]).default("one-for-one"),
});
/**
 * Supervisor heartbeat parameters
 */
export const SupervisorHeartbeatParams = z.object({
    /** Process ID of the component */
    pid: z.number().int().positive(),
});
/**
 * System health parameters
 */
export const SystemHealthParams = z.object({
    /** Include verbose details */
    verbose: z.boolean().optional(),
});
// =============================================================================
// Daemon Lifecycle Results
// =============================================================================
export const DaemonPingResult = z.object({
    pong: z.literal(true),
    uptime: z.number(),
    version: z.string(),
});
export const DaemonStatusResult = z.object({
    pid: z.number().int(),
    version: z.string(),
    uptime: z.number(),
    startedAt: z.string(),
    workspaces: z.number().int().nonnegative(),
    connections: z.number().int().nonnegative(),
    memoryUsage: z.object({
        heapUsed: z.number(),
        heapTotal: z.number(),
        rss: z.number(),
    }),
    lastActivity: z.number(),
    idleTimeout: z.number(),
    auth: z
        .object({
        authenticated: z.boolean(),
        user: z.string().optional(),
        tier: z.string().optional(),
    })
        .optional(),
});
export const DaemonStopResult = z.object({
    shutting_down: z.literal(true),
});
export const DaemonReloadResult = z.object({
    reloaded: z.literal(true),
});
// =============================================================================
// Supervisor Results
// =============================================================================
export const SupervisorRegisterResult = z.object({
    registered: z.literal(true),
    pid: z.number().int().positive(),
    type: z.enum(["mcp-stdio", "mcp-http"]),
});
export const SupervisorHeartbeatResult = z.object({
    acknowledged: z.boolean(),
    error: z.string().optional(),
});
export const SystemHealthResult = z.object({
    status: z.string(),
    uptime: z.number(),
    workspaces: z.number().int().nonnegative(),
    activeSessions: z.number().int().nonnegative(),
    supervisedComponents: z.number().int().nonnegative(),
    memory: z
        .object({
        heapUsed: z.number(),
        heapTotal: z.number(),
        rss: z.number(),
    })
        .optional(),
    components: z
        .array(z
        .object({
        pid: z.number().int().positive(),
        type: z.string(),
        lastHeartbeat: z.string(),
    })
        .passthrough())
        .optional(),
});
