// ESM imports fixed for Node.js v22+
/**
 * Validation Parameter Schemas
 *
 * Validation and violation related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/validation
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
// =============================================================================
// Validation Params
// =============================================================================
/**
 * Quick validate parameters
 */
export const ValidateQuickParams = WorkspaceBase.extend({
    /** Single file */
    file: z.string().optional(),
    /** Multiple files */
    files: z.array(z.string()).optional(),
    /** Run tests */
    runTests: z.boolean().optional(),
    /** Skip TypeScript check */
    skipTypeScript: z.boolean().optional(),
    /** Skip tests */
    skipTests: z.boolean().optional(),
    /** Skip lint */
    skipLint: z.boolean().optional(),
});
/**
 * Comprehensive validate parameters
 */
export const ValidateComprehensiveParams = WorkspaceBase.extend({
    /** Code to validate */
    code: z.string(),
    /** File path */
    filePath: z.string().min(1),
});
// =============================================================================
// Violation Params
// =============================================================================
/**
 * Report violation parameters
 */
export const ViolationReportParams = WorkspaceBase.extend({
    /** Violation type */
    type: z.string().min(1),
    /** File where violation occurred */
    file: z.string().min(1),
    /** What happened */
    whatHappened: z.string().min(1),
    /** Why it happened */
    whyItHappened: z.string().min(1),
    /** How to prevent it */
    prevention: z.string().min(1),
});
/**
 * Check path safety parameters
 */
export const ValidationCheckPathParams = z.object({
    /** Absolute path to check */
    path: z.string().min(1),
    /** Absolute workspace root to check against */
    workspace: z.string().min(1),
});
/**
 * List violations parameters
 */
export const ViolationListParams = WorkspaceBase;
// =============================================================================
// Validation Result Schemas (VALID-T Batch 3)
// =============================================================================
const ValidationCheckResult = z.object({
    passed: z.boolean(),
    errors: z.number().int().nonnegative(),
});
export const ValidateQuickResult = z.object({
    passed: z.boolean(),
    checks: z.object({
        typescript: ValidationCheckResult,
        lint: ValidationCheckResult,
        tests: ValidationCheckResult,
    }),
    fileCount: z.number().int().nonnegative(),
    duration: z.number().nonnegative(),
});
export const ValidateComprehensiveResult = z.object({
    passed: z.boolean(),
    confidence: z.number(),
    totalIssues: z.number().int().nonnegative(),
    recommendation: z.string(),
    focusPoints: z.array(z.unknown()),
    layers: z.array(z.unknown()),
});
// =============================================================================
// Violation Result Schemas (VALID-T Batch 2)
// =============================================================================
export const ViolationReportResult = z.discriminatedUnion("reported", [
    z.object({
        reported: z.literal(true),
        type: z.string(),
        file: z.string(),
        status: z.unknown(),
    }),
    z.object({
        reported: z.literal(false),
        error: z.string(),
    }),
]);
export const ViolationListResult = z.object({
    violations: z.array(z.unknown()),
    total: z.number().int().nonnegative(),
});
