// ESM imports fixed for Node.js v22+
import { z } from "zod";
import { MethodSchemas } from "../local-service/schemas/registry.js";
// ============================================================================
// Schema Definitions (one per method)
// ============================================================================
export const SnapshotCreateSchema = z.object({
    filePath: z.string(),
    content: z.string().optional(),
    trigger: z.enum(["save", "manual", "auto"]),
});
export const SnapshotRestoreSchema = z.object({
    snapshotId: z.string(),
    filePath: z.string().optional(),
});
export const SnapshotListSchema = z.object({
    filePath: z.string().optional(),
    limit: z.number().optional(),
});
export const SnapshotDeleteSchema = z.object({
    snapshotId: z.string(),
    permanent: z.boolean().optional(),
});
export const SnapshotBulkDeleteSchema = z.object({
    snapshotIds: z.array(z.string()),
});
export const SnapshotProtectSchema = z.object({
    snapshotId: z.string(),
});
export const SnapshotUnprotectSchema = z.object({
    snapshotId: z.string(),
});
export const SnapshotRenameSchema = z.object({
    snapshotId: z.string(),
    newName: z.string(),
});
export const ContextCompileSchema = z.object({
    filePaths: z.array(z.string()),
    includeDependencies: z.boolean().optional(),
});
export const ContextCheckPatternsSchema = z.object({
    filePaths: z.array(z.string()),
});
export const ContextGetSchema = z.object({
    workspace: z.string(),
});
export const DaemonStatusSchema = z.object({
    includeMetrics: z.boolean().optional(),
});
export const DaemonStartSchema = z.object({
    port: z.number().optional(),
    configPath: z.string().optional(),
});
export const DaemonStopSchema = z.object({
    force: z.boolean().optional(),
});
export const AuthHandshakeInitiateSchema = z.object({
    clientId: z.string(),
    publicKey: z.string(),
});
export const AuthHandshakeCompleteSchema = z.object({
    challengeId: z.string(),
    signature: z.string(),
});
// Learning methods
export const LearningPruneSchema = z.object({
    workspace: z.string(),
    olderThanDays: z.number().optional(),
});
export const LearningGcSchema = z.object({
    workspace: z.string(),
    operation: z.enum(["all", "stale", "orphaned"]).optional(),
    dryRun: z.boolean().optional(),
});
export const LearningListSchema = z.object({
    workspace: z.string(),
    limit: z.number().optional(),
    type: z.string().optional(),
});
export const LearningSearchSchema = z.object({
    workspace: z.string(),
    keywords: z.array(z.string()),
    limit: z.number().optional(),
});
export const LearningAddSchema = z.object({
    workspace: z.string(),
    learning: z.record(z.unknown()),
});
// Violation methods (VSUI-03 FIX)
export const ViolationListSchema = z.object({
    workspace: z.string(),
});
export const ViolationReportSchema = z.object({
    workspace: z.string(),
    type: z.string(),
    file: z.string(),
    whatHappened: z.string(),
    whyItHappened: z.string(),
    prevention: z.string(),
});
// Core initialization
export const InitializeSchema = z.object({
    config: z.record(z.unknown()).optional(),
});
// Health methods
export const HealthPingSchema = z.object({
    includeUptime: z.boolean().optional(),
});
// Daemon lifecycle methods
export const DaemonPingSchema = z.object({});
export const DaemonShutdownSchema = z.object({
    force: z.boolean().optional(),
});
// Session methods (additional)
export const SessionChangesSchema = z.object({
    sessionId: z.string(),
    since: z.string().optional(),
});
// Validation methods
export const ValidateQuickSchema = z.object({
    filePaths: z.array(z.string()),
    checks: z.array(z.string()).optional(),
});
export const ValidateComprehensiveSchema = z.object({
    filePaths: z.array(z.string()),
    checks: z.array(z.string()).optional(),
});
// Watch methods
export const WatchFileChangedSchema = z.object({
    filePath: z.string(),
    eventType: z.enum(["create", "modify", "delete"]),
    content: z.string().optional(),
});
export const WatchSubscribeSchema = z.object({
    workspace: z.string(),
    filePaths: z.array(z.string()),
});
export const WatchUnsubscribeSchema = z.object({
    workspace: z.string(),
    subscriptionId: z.string(),
});
export const MpcFileModifiedSchema = z.object({
    workspace: z.string(),
    path: z.string(),
    linesChanged: z.number().optional(),
    aiAttributed: z.boolean().optional(),
    aiTool: z.string().optional(),
});
export const IntelligenceFileModifiedSchema = z.object({
    workspace: z.string(),
    path: z.string(),
    linesChanged: z.number().optional(),
    aiAttributed: z.boolean().optional(),
    aiTool: z.string().optional(),
});
// Baseline methods
export const BaselineWorkspaceSchema = z.object({
    workspace: z.string(),
});
export const BaselineInvalidateSchema = z.object({
    cacheKey: z.string().optional(),
});
// Protection methods
export const ProtectionSetLevelSchema = z.object({
    workspace: z.string(),
    level: z.enum(["none", "read-only", "full"]),
});
export const ProtectionListDaemonSchema = z.object({});
export const ProtectionGetLevelSchema = z.object({
    workspace: z.string(),
});
// Session methods
export const SessionStartSchema = z.object({
    workspacePath: z.string(),
    task: z.string().optional(),
    files: z.array(z.string()).optional(),
    keywords: z.array(z.string()).optional(),
    metadata: z.record(z.unknown()).optional(),
    touchedFiles: z.array(z.string()).optional(),
});
export const SessionEndSchema = z.object({
    sessionId: z.string().optional(),
    reason: z.enum(["user", "idle", "workspace_closed", "recovered-abandoned"]).optional(),
});
export const SessionListSchema = z.object({
    workspacePath: z.string().optional(),
    limit: z.number().int().min(1).max(100).default(20),
    before: z.string().optional(),
    includeEnded: z.boolean().default(true),
});
export const SessionVitalsSchema = z.object({
    workspacePath: z.string(),
});
export const SessionReviewSchema = z.object({
    workspacePath: z.string(),
    sessionId: z.string().optional(),
    files: z.array(z.string()).optional(),
    includeCommitMessage: z.boolean().optional(),
    skipPatterns: z.boolean().optional(),
});
// Snapshot methods
export const SnapshotGetSchema = z.object({
    snapshotId: z.string(),
    includeContent: z.boolean().default(false),
});
export const SnapshotDiffSchema = z.object({
    baseSnapshotId: z.string(),
    compareSnapshotId: z.string().optional(),
    contextLines: z.number().int().min(0).max(10).default(3),
    format: z.enum(["unified", "split"]).default("unified"),
});
// Protection methods
export const ProtectionEvaluateSchema = z.object({
    filePath: z.string().min(1),
    content: z.string().optional(),
    context: z
        .object({
        recentChanges: z.number().int().nonnegative().optional(),
        timeSinceLastSave: z.number().int().nonnegative().optional(),
        aiToolActive: z.boolean().optional(),
    })
        .optional(),
});
// Detection methods
export const DetectionCheckSchema = z.object({
    filePath: z.string().min(1),
    content: z.string(),
    previousContent: z.string().optional(),
    metadata: z
        .object({
        editorInfo: z.string().optional(),
        timestamp: z.number().int().positive().optional(),
    })
        .optional(),
});
export const SessionCurrentSchema = z.object({
    workspacePath: z.string().optional(),
});
export const SessionEndDaemonSchema = z.object({
    sessionId: z.string(),
});
export const SessionStatusSchema = z.object({
    sessionId: z.string(),
});
