// ============================================================================
// Runtime Validation
// ============================================================================
export function isRegisteredMethod(method) {
    return method in METHOD_REGISTRY;
}
export function validateMethodParams(method, params) {
    const schema = METHOD_REGISTRY[method].schema;
    return schema.parse(params);
}
export function getMethodDefinition(method) {
    return METHOD_REGISTRY[method];
}
/**
 * Type-safe RPC method call helper
 * Validates method is registered and params match schema at compile time
 */
export function callMethod(method, params) {
    // Runtime validation
    if (!isRegisteredMethod(method)) {
        return {
            success: false,
            error: `Unregistered method: ${method}`,
        };
    }
    try {
        // Validate params against schema
        const validated = validateMethodParams(method, params);
        return {
            success: true,
            data: validated,
        };
    }
    catch (error) {
        return {
            success: false,
            error: error instanceof Error ? error.message : String(error),
        };
    }
}
/**
 * Async version for actual RPC calls
 * Use this when making actual network/daemon calls
 */
export async function callMethodAsync(client, method, params) {
    if (!isRegisteredMethod(method)) {
        throw new Error(`Unregistered method: ${method}`);
    }
    // Validate before sending
    validateMethodParams(method, params);
    // Make the actual call
    return client.call(method, params);
}
// ============================================================================
// Legacy Method Name Normalization
// ============================================================================
/**
 * Normalize a method name to its canonical form
 * - If already registered: return as-is
 * - If in legacy alias map: log warning and return canonical name
 * - Otherwise: throw error
 */
export function normalizeMethod(method, warn) {
    // Already canonical
    if (isRegisteredMethod(method)) {
        return method;
    }
    // Legacy alias
    if (method in LEGACY_ALIAS_MAP) {
        const canonical = LEGACY_ALIAS_MAP[method];
        if (warn) {
            warn(`Deprecated method name: ${method}, use ${canonical}`);
        }
        return canonical;
    }
    throw new Error(`Unknown method: ${method}`);
}
