// ESM imports fixed for Node.js v22+
/**
 * Learning Parameter Schemas
 *
 * All learning-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/learning
 */
import { z } from "zod";
import { LearningType } from "./primitives.js";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Add learning parameters
 */
export const LearningAddParams = WorkspaceBase.extend({
    /** Learning type */
    type: LearningType,
    /** Trigger condition */
    trigger: z.string().min(1),
    /** Action to take */
    action: z.string().min(1),
    /** Source of the learning */
    source: z.string().optional(),
});
/**
 * Search learnings parameters
 */
export const LearningSearchParams = WorkspaceBase.extend({
    /** Keywords to search */
    keywords: z.array(z.string()).min(1),
    /** Max results */
    limit: z.number().int().min(1).max(100).optional(),
});
/**
 * List learnings parameters
 */
export const LearningListParams = WorkspaceBase.extend({
    /** Max results */
    limit: z.number().int().min(1).max(200).optional(),
});
/**
 * Prune learnings parameters
 */
export const LearningPruneParams = WorkspaceBase;
/**
 * Evaluate learnings parameters
 */
export const LearningEvaluateParams = WorkspaceBase.extend({
    /** Command being evaluated */
    commandName: z.string().min(1),
    /** Command arguments */
    args: z.record(z.unknown()).optional(),
    /** Files or paths involved */
    filesOrPaths: z.array(z.string()).optional(),
    /** Intent of the command */
    intent: z.enum(["implement", "debug", "refactor", "review"]).optional(),
    /** Learning mode */
    mode: z.enum(["observe", "warn", "apply-safe", "apply-all", "off"]).optional(),
});
/**
 * Update session learnings parameters
 */
export const LearningUpdateSessionParams = WorkspaceBase.extend({
    /** Session ID */
    sessionId: z.string().min(1),
    /** Learning IDs to associate */
    learningIds: z.array(z.string()),
});
/**
 * Learning GC parameters
 */
export const LearningGCParams = WorkspaceBase.extend({
    /** GC operation */
    operation: z.enum(["archive", "delete", "all"]).optional(),
    /** Dry run (audit only) */
    dryRun: z.boolean().default(true),
});
/**
 * Queue a learning for cloud sync (F1: routes through daemon IPC instead of direct StateStore)
 */
export const LearningQueueParams = z.object({
    workspace: z.string().min(1),
    patternKey: z.string().min(1),
    patternType: z.string().min(1),
    confidence: z.number().min(0).max(1),
});
/**
 * Get pending sync items from daemon's StateStore
 */
export const LearningQueueSyncParams = z.object({
    workspace: z.string().min(1),
    maxBatchSize: z.number().int().positive().max(1000).optional(),
});
/**
 * Mark synced/failed items after cloud sync attempt
 */
export const LearningQueueSyncCompleteParams = z.object({
    workspace: z.string().min(1),
    syncedIds: z.array(z.string()),
    failedIds: z.array(z.string()),
});
// =============================================================================
// VALID-04: Learning Result Schemas
// =============================================================================
/**
 * Result for learning/add
 * Shape derived from createLearningService().add() return value.
 */
export const LearningAddResultV4 = z.object({
    success: z.boolean(),
    learningId: z.string(),
    type: z.string(),
    trigger: z.string(),
    action: z.string(),
    confidence: z.number(),
    captureMethod: z.string(),
});
/**
 * Learning entry shape shared by search and evaluate responses.
 */
const LearningEntryItem = z.object({
    type: z.string(),
    trigger: z.string(),
    action: z.string(),
    relevanceScore: z.number().optional(),
});
/**
 * Result for learning/search
 */
export const LearningSearchResultV4 = z.object({
    learnings: z.array(LearningEntryItem),
    total: z.number().int(),
});
/**
 * Result for learning/list
 */
export const LearningListResultV4 = z.object({
    learnings: z.array(z.object({
        type: z.string(),
        trigger: z.string(),
        action: z.string(),
    })),
    total: z.number().int(),
});
/**
 * Result for learning/prune
 * Shape from intelligence.pruneLearnings() return type.
 */
export const LearningPruneResult = z.object({
    pruned: z.number().int(),
    remaining: z.number().int(),
    categories: z.object({
        lowConfidence: z.number().int(),
        stale: z.number().int(),
        duplicates: z.number().int(),
    }),
});
/**
 * Result for learning/gc
 * Shape from learning service gc() return value (wraps intelligence.gcLearnings()).
 */
export const LearningGCResult = z.object({
    operation: z.string(),
    dryRun: z.boolean(),
    collected: z.number().int(),
    remaining: z.number().int(),
    categories: z.object({
        malformed: z.number().int(),
        invalidType: z.number().int(),
        emptyContent: z.number().int(),
    }),
});
/**
 * Result for learning/evaluate
 */
export const LearningEvaluateResultV4 = z.object({
    applicable: z.array(LearningEntryItem),
    mode: z.string(),
    commandName: z.string(),
});
/**
 * Result for learning/update-session
 */
export const LearningUpdateSessionResult = z.object({
    success: z.boolean(),
    sessionId: z.string(),
    updated: z.number().int(),
});
/**
 * Result for learning/seed
 * Shape from createLearningService().seed() explicit return type.
 */
export const LearningSeedResult = z.object({
    seeded: z.boolean(),
    learningsAdded: z.number().int(),
    tiers: z.object({
        hot: z.number().int(),
        warm: z.number().int(),
        cold: z.number().int(),
    }),
    alreadySeeded: z.boolean(),
    framework: z.string().nullable(),
});
/**
 * Result for learning/consolidate
 */
export const LearningConsolidateResult = z.object({
    success: z.boolean(),
    originalCount: z.number().int(),
    consolidatedCount: z.number().int(),
    duplicatesFound: z.number().int(),
    reductionPercent: z.number(),
    archivePath: z.string(),
    dryRun: z.boolean(),
});
/**
 * Result for learning/track-applied
 * Shape from createLearningService().trackApplied() explicit return type.
 */
export const LearningTrackAppliedResult = z.object({
    success: z.boolean(),
    newConfidence: z.number().optional(),
    error: z.string().optional(),
});
/**
 * Result for learning/observe-pattern
 * Shape from createLearningService().observePattern() explicit return type.
 */
export const LearningObservePatternResult = z.object({
    promoted: z.boolean(),
    observationCount: z.number().int(),
    patternId: z.string(),
});
