/**
 * Workspace Base Schema
 *
 * Base params that carry workspace identity.
 * All daemon methods that target a specific workspace extend this.
 *
 * @module @vreko/contracts/local-service/schemas/workspace-base
 */
import { z } from "zod";
/**
 * Base params that carry workspace identity.
 * All daemon methods that target a specific workspace extend this.
 */
export const WorkspaceBase = z.object({
    /** Absolute path to workspace root */
    workspace: z.string().min(1),
});
