// ESM imports fixed for Node.js v22+
/**
 * Workspace Parameter Schemas
 *
 * All workspace-level operation request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/workspace
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Workspace analyze parameters (5-phase composite operation)
 */
export const WorkspaceAnalyzeParams = WorkspaceBase.extend({
    /** Skip baseline computation (faster, less complete) */
    skipBaseline: z.boolean().optional(),
    /** Skip learning seeding */
    skipLearnings: z.boolean().optional(),
    /** Force re-seed learnings even if already seeded */
    forceSeedLearnings: z.boolean().optional(),
});
/**
 * Workspace status parameters (quick check without full analysis)
 */
export const WorkspaceStatusParams = WorkspaceBase;
/**
 * Workspace seed-knowledge parameters
 */
export const WorkspaceSeedKnowledgeParams = WorkspaceBase.extend({
    /** Optional path to global knowledge DB (defaults to ~/.vreko/knowledge.db) */
    globalDbPath: z.string().optional(),
});
/**
 * Workspace fingerprint parameters
 *
 * Fingerprints the workspace to classify activity level and detect AI tool configs.
 * Called during extension activation to determine onboarding path.
 */
export const WorkspaceFingerprintParams = WorkspaceBase;
/**
 * Workspace hydrate parameters
 *
 * Hydrates workspace state from persisted daemon context.
 * Called when the extension reconnects to an already-running daemon
 * to restore session state, refresh configs, and report knowledge entries.
 */
export const WorkspaceHydrateParams = WorkspaceBase;
/**
 * Workspace resolve-id parameters
 *
 * Resolves the stable workspace ID from git remote, local hash, or fallback.
 * Called by the VS Code extension to obtain the workspace identity used for
 * cloud sync and session scoping.
 */
export const WorkspaceResolveIdParams = WorkspaceBase.extend({
    /** Optional existing user-supplied ID to use as a fallback */
    fallbackUserId: z.string().optional(),
    /** Whether to persist the resolved ID back to .vreko/config.json */
    autoPersist: z.boolean().optional().default(true),
});
/**
 * Workspace init parameters
 *
 * Initialises the .vreko directory structure for a workspace.
 * Called by the VS Code extension after the user triggers "Init Workspace"
 * so the extension never needs direct filesystem access.
 */
export const WorkspaceInitParams = WorkspaceBase;
/**
 * Workspace trigger-workspace-json-write parameters
 *
 * Triggers immediate workspace.json write for a workspace.
 * Emits a synthetic workspace.initialized event to bypass the 5-minute debounce.
 * Called by vreko init to ensure workspace.json exists immediately after setup.
 */
export const WorkspaceTriggerWorkspaceJsonWriteParams = WorkspaceBase;
/**
 * Workspace write-from-scan-profile parameters
 *
 * Triggers a daemon-side runInitScan and writes workspace.json with the result.
 * Default (force absent/false): additive merge — scan-derived coChange/fragility
 * arrays are overlaid onto existing live observations without resetting counters.
 * With force=true: full overwrite, resets to BOOTSTRAP state (observationCount=0).
 * Use force only when you need a clean slate (broken file, major git history rewrite).
 *
 * Security: no numeric inputs from CLI  -  profile is produced by daemon's own scan.
 * Trust boundary: local Unix socket / named pipe only.
 */
export const WorkspaceWriteFromScanProfileParams = WorkspaceBase.extend({
    force: z.boolean().optional(),
});
/**
 * Workspace run-init-scan parameters
 *
 * Triggers a daemon-side runInitScan via the scan-service (24h cache + mutex dedup).
 * Called by the CLI Scanning TUI frame via IPC instead of importing intelligence directly.
 * Returns RecoveryRiskProfile | null (null = cache hit or concurrent scan in progress).
 *
 * ARCH-01: CLI must NOT import @vreko/intelligence directly. This IPC method is the
 * approved delegation path.
 */
export const WorkspaceRunInitScanParams = WorkspaceBase;
// =============================================================================
// Workspace State Machine (C2 activation lifecycle)
// =============================================================================
/**
 * workspace/state  -  parameters
 *
 * Returns the current activation state for a workspace.
 * Handler: apps/local-service/src/server/protocol.ts case "workspace" → "state"
 * No external callers; only exercised in protocol-phantom.test.ts.
 * Decision: REGISTER (keep handler, add schema  -  delete deferred pending C2 phase).
 */
export const WorkspaceStateParams = WorkspaceBase;
/**
 * workspace/transition  -  parameters
 *
 * Triggers a state machine transition for a workspace.
 * Handler: apps/local-service/src/server/protocol.ts case "workspace" → "transition"
 * No external callers; only exercised in protocol-phantom.test.ts.
 */
export const WorkspaceTransitionParams = WorkspaceBase.extend({
    /** Target state to transition to */
    targetState: z.string().optional(),
    /** Reason for the transition */
    reason: z.string().optional(),
});
/**
 * workspace/should-scan  -  parameters
 *
 * Returns whether the workspace should run an init scan (scan-once enforcement).
 * Handler: apps/local-service/src/server/protocol.ts case "workspace" → "should-scan"
 * No external callers; only exercised in protocol-phantom.test.ts.
 */
export const WorkspaceShouldScanParams = WorkspaceBase;
// =============================================================================
// Workspace Result Schemas (VALID-T Batch 4)
// =============================================================================
export const WorkspaceSeedKnowledgeResult = z.object({
    seeded: z.number().int().nonnegative(),
    alreadyPresent: z.number().int().nonnegative(),
});
export const WorkspaceResolveIdResult = z.object({
    workspaceId: z.string(),
    isTeamStable: z.boolean(),
    source: z.enum(["config", "git", "local", "user", "fallback", "path"]),
});
export const WorkspaceInitResult = z.object({
    initialized: z.boolean(),
});
export const WorkspaceStateResult = z.object({
    state: z.string(),
});
export const WorkspaceTransitionResult = z.object({
    state: z.string(),
    changed: z.boolean(),
});
export const WorkspaceShouldScanResult = z.object({
    shouldScan: z.boolean(),
});
