// ESM imports fixed for Node.js v22+
/**
 * Session Parameter Schemas
 *
 * All session-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/session
 */
import { z } from "zod";
import { BootProfile } from "./boot-profile.js";
import { ClientType } from "./primitives.js";
// =============================================================================
// Session Params (Original Local-Service Style)
// =============================================================================
/**
 * Initialize request parameters
 *
 * First request sent by client to establish connection.
 */
export const InitializeParams = z.object({
    /** Protocol version the client supports */
    protocolVersion: z.string().regex(/^\d+\.\d+\.\d+$/),
    /** Client type identifying the connecting surface */
    clientType: ClientType.optional().default("unknown"),
    /** Client version (semantic versioning) */
    clientVersion: z.string().optional().default("0.0.0"),
    /** Client identification (legacy field, kept for backward compatibility) */
    clientInfo: z
        .object({
        /** Client name (e.g., "vscode-extension", "cli") */
        name: z.string().min(1).max(100),
        /** Client version (semantic versioning) */
        version: z.string(),
    })
        .optional(),
    /** Client capabilities (optional) */
    capabilities: z
        .object({
        /** Client accepts server-sent notifications */
        notifications: z.boolean().default(true),
        /** Client can handle base64-encoded binary content */
        binaryContent: z.boolean().default(false),
    })
        .optional(),
});
/**
 * Initialize response  -  returned by the daemon on successful initialize handshake.
 */
export const InitializeResponse = z.object({
    protocolVersion: z.string(),
    serverInfo: z.object({
        name: z.string(),
        version: z.string(),
    }),
    capabilities: z
        .object({
        notifications: z.boolean().optional(),
        binaryContent: z.boolean().optional(),
        health: z.record(z.boolean()).optional(),
    })
        .optional(),
    /** True when the daemon is starting for the first time (VIRGIN boot profile) */
    isFirstRun: z.boolean().default(false),
    /** Boot profile selected for this startup */
    bootProfile: BootProfile.optional(),
});
/**
 * Health check parameters
 */
export const HealthCheckParams = z.object({
    /** Include detailed health information */
    verbose: z.boolean().optional(),
});
/**
 * Session current parameters
 */
export const SessionCurrentParams = z.object({
    /** Filter by workspace path (optional) */
    workspacePath: z.string().optional(),
});
/**
 * Session workspace-scoped base parameters.
 *
 * Session RPCs use workspacePath rather than the older workspace key so the
 * daemon/client contract stays consistent across surfaces.
 */
const SessionWorkspacePathBase = z.object({
    /** Absolute path to workspace root */
    workspacePath: z.string().min(1),
});
/**
 * Shared session creation parameters.
 *
 * Canonical payload for session/start.
 */
const SessionCreateParamsBase = SessionWorkspacePathBase.extend({
    /** Optional task description */
    task: z.string().min(1).optional(),
    /** Files involved in this task */
    files: z.array(z.string()).optional(),
    /** Keywords for context matching */
    keywords: z.array(z.string()).optional(),
    /** Files touched during session creation */
    touchedFiles: z.array(z.string()).optional(),
});
/**
 * Session start parameters
 */
export const SessionStartParams = SessionCreateParamsBase.extend({
    /** Additional session metadata (optional) */
    metadata: z
        .object({
        /** Editor name (e.g., "Visual Studio Code") */
        editorName: z.string().optional(),
        /** Editor version */
        editorVersion: z.string().optional(),
    })
        .optional(),
});
/**
 * Session end parameters
 */
export const SessionEndParams = z.object({
    /** Session to end (defaults to current session if omitted) */
    sessionId: z.string().min(1).optional(),
    /** Reason for ending session */
    reason: z.enum(["user", "idle", "workspace_closed", "recovered-abandoned"]).optional(),
});
/**
 * Session list parameters
 */
export const SessionListParams = z.object({
    /** Filter by workspace path (optional) */
    workspacePath: z.string().optional(),
    /** Maximum number of sessions to return */
    limit: z.number().int().min(1).max(100).default(20),
    /** Pagination cursor (session ID to start after) */
    before: z.string().min(1).optional(),
    /** Include ended sessions in results */
    includeEnded: z.boolean().default(true),
});
// =============================================================================
// Session Extended Params (Daemon-style session.start / session.end)
// =============================================================================
/**
 * Session end parameters (daemon-style)
 */
export const SessionEndDaemonParams = SessionWorkspacePathBase.extend({
    /** Session to end (optional; defaults to current workspace session) */
    sessionId: z.string().min(1).optional(),
    /**
     * Free-text outcome description  -  what was accomplished, what remains, decisions made.
     * Becomes the opening context for the next session briefing.
     * Do NOT constrain to an enum: the MCP tool description promises free-text paragraphs.
     */
    outcome: z.string().min(1).max(2000).optional(),
    /** Additional notes */
    notes: z.string().optional(),
    /** Create a snapshot on end */
    createSnapshot: z.boolean().optional(),
    /** Learning IDs to accept */
    acceptLearnings: z.array(z.number()).optional(),
});
/**
 * Session status parameters (daemon-style)
 */
export const SessionStatusParams = SessionWorkspacePathBase.extend({
    /** Session to inspect (optional; defaults to current workspace session) */
    sessionId: z.string().min(1).optional(),
});
/**
 * Session review parameters
 */
export const SessionReviewParams = SessionWorkspacePathBase.extend({
    /** Session ID to review */
    sessionId: z.string().min(1).optional(),
    /** Files to review */
    files: z.array(z.string()).optional(),
    /** Include commit message suggestion */
    includeCommitMessage: z.boolean().optional(),
    /** Skip pattern checking */
    skipPatterns: z.boolean().optional(),
});
/**
 * Session changes parameters
 */
export const SessionChangesParams = SessionWorkspacePathBase.extend({
    /** Session to inspect (optional; defaults to current workspace session) */
    sessionId: z.string().min(1).optional(),
    /** Include diff in results */
    includeDiff: z.boolean().optional(),
    /** Filter to specific files */
    filterFiles: z.array(z.string()).optional(),
    /** Include AI attribution info */
    includeAIAttribution: z.boolean().default(true),
});
/**
 * Session vitals parameters (Pass 2 - Single Source of Truth)
 */
export const SessionVitalsParams = SessionWorkspacePathBase;
/**
 * Session list-ceremonies parameters
 * Returns sessions in ceremony format for the Closing Ceremony Theater WebView
 */
export const SessionListCeremoniesParams = z.object({
    /** Filter by workspace path */
    workspacePath: z.string().min(1),
    /** Pagination cursor (session ID) */
    cursor: z.string().optional(),
    /** Max number of sessions to return (default 20) */
    limit: z.number().optional(),
});
/**
 * Session vitals result
 * Computed from session registry (touchedFiles, snapshotIds, learningIds)
 */
export const SessionVitalsResult = z.object({
    /** Pulse level based on file count thresholds */
    pulse: z.enum(["resting", "elevated", "racing", "critical"]),
    /** Pressure: ratio of unprotected changes (0-100) */
    pressure: z.number().min(0).max(100),
    /** Trajectory based on pressure level */
    trajectory: z.enum(["stable", "increasing", "decreasing"]),
    /** Whether a snapshot is recommended */
    snapshotRecommended: z.boolean(),
    /** Files modified during session */
    filesModified: z.number(),
    /** Snapshots created during session */
    snapshotsCreated: z.number(),
    /** Learnings captured during session */
    learningsCaptured: z.number(),
});
/**
 * Session update-task parameters (update the active task description mid-session)
 */
export const SessionUpdateTaskParams = SessionWorkspacePathBase.extend({
    /** Session to update (optional; defaults to current workspace session) */
    sessionId: z.string().min(1).optional(),
    /** New task description */
    task: z.string().min(1),
});
/**
 * session/report-ai-tool  -  parameters
 *
 * Reports detection of an AI coding tool in the active session.
 * Handler: apps/local-service/src/server/protocol.ts case "session" → "report-ai-tool"
 * Callers: apps/vscode/src/services/daemon-bridge/DaemonOperations.ts reportAiTool()
 *
 * Phantom resolved: method was routed but absent from MethodSchemas (blocked at isValidMethod).
 * Refs: deep-daemon-audit-2026-05-11.md Phase 1, implementation-prompt-2026-05-11.md Phase 1
 */
export const SessionReportAiToolParams = z.object({
    /** Absolute path to the workspace root */
    workspacePath: z.string().min(1),
    /** Session to update (optional; defaults to current workspace session) */
    sessionId: z.string().optional(),
    /** The AI tool detected */
    tool: z.enum(["cursor", "copilot", "claude-code", "windsurf", "continue", "other"]),
    /** Tool version string if available */
    toolVersion: z.string().optional(),
    /** ISO 8601 timestamp of detection */
    detectedAt: z.string().datetime().optional(),
});
/**
 * session/report-ai-tool  -  result
 */
export const SessionReportAiToolResult = z.object({
    /** Whether the daemon acknowledged and recorded the detection */
    acknowledged: z.boolean(),
    /** The session that was updated (null if no active session) */
    sessionId: z.string().nullable(),
});
