/**
 * WAL Ledger Event Schemas
 *
 * Defines the LedgerEvent schema for the per-workspace Write-Ahead Log (WAL).
 * Every action event is appended to the per-workspace WAL as a LedgerEvent.
 *
 * Privacy invariant: NO file content in LedgerEvent — metadata and hashes only (ARCH-03).
 *
 * @module @vreko/contracts/local-service/schemas/ledger
 */
import { z } from "zod";
// =============================================================================
// CanonicalVerb — action vocabulary for WAL events
// =============================================================================
/**
 * Canonical verb vocabulary for LedgerEvent actions.
 * Aligns with AgentAction enum in @vreko/infrastructure/observability/vocabulary.ts
 * but expressed as a Zod enum for IPC schema validation.
 */
export const CanonicalVerb = z.enum([
    // File operations
    "WRITE_FILE",
    "EDIT_FILE",
    "DELETE_FILE",
    "READ_FILE",
    // Reasoning
    "PLAN",
    "REVIEW",
    "DECIDE",
    // Verification
    "VERIFY_GATE",
    // Session lifecycle
    "SESSION_START",
    "SESSION_END",
    "SESSION_HEARTBEAT",
    // Snapshot operations
    "SNAPSHOT_CREATE",
    "SNAPSHOT_RESTORE",
    "SNAPSHOT_ROLLBACK",
    // Phase events
    "PHASE_START",
    "PHASE_END",
    // Catchall for extension
    "OTHER",
]);
// =============================================================================
// LedgerEvent
// =============================================================================
/**
 * A single action event in the per-workspace WAL.
 *
 * Privacy invariant (ARCH-03): meta MUST NOT contain file content.
 * Only metadata (file paths, hashes, counts) is permitted.
 *
 * seq: per-surface monotonic counter for interleave ordering (WAL-06).
 */
export const LedgerEvent = z.object({
    /** Surface identifier (e.g. "vscode:session-abc123", "cli:run-xyz") */
    surfaceId: z.string(),
    /** Workspace fingerprint: sha256("gitRemote:userId") from sync-client.ts */
    workspaceFingerprint: z.string(),
    /** Per-surface monotonic sequence number for ordering (WAL-06 interleave resolution) */
    seq: z.number().int().min(0),
    /** Epoch milliseconds */
    ts: z.number().int().positive(),
    /** Canonical action verb */
    verb: CanonicalVerb,
    /**
     * Event metadata — NO file content permitted (ARCH-03).
     * Allowed: file paths (relative), hashes, counts, durations, error codes.
     */
    meta: z.record(z.unknown()),
});
// =============================================================================
// ledger/append params + result
// =============================================================================
/**
 * Parameters for ledger/append IPC method.
 * Appends a LedgerEvent to the per-workspace WAL.
 */
export const LedgerAppendParams = LedgerEvent;
export const LedgerAppendResult = z.object({
    /** WAL file offset after the appended entry (byte position) */
    offset: z.number().int().min(0),
    /** Acknowledged: true if write was confirmed synchronous (appendFileSync) */
    acked: z.boolean(),
});
// =============================================================================
// ledger/recover params + result
// =============================================================================
/**
 * Parameters for ledger/recover IPC method.
 * Reconstructs a session ceremony from the WAL for expired/crashed sessions.
 *
 * WAL-04: The critical fix for the 73-minute swarm failure.
 * vreko_end on an expired session calls this to reconstruct ceremony from disk.
 */
export const LedgerRecoverParams = z.object({
    /** Session ID to recover */
    sessionId: z.string(),
    /** Workspace fingerprint (routing key to the correct WAL file) */
    workspaceFingerprint: z.string(),
});
/**
 * Verb summary: count per verb in the recovered session.
 */
export const VerbSummary = z.record(z.number().int().min(0));
/**
 * Recovery result — the ceremony reconstructed from WAL events.
 *
 * This is what vreko_end returns when the session handle has expired:
 * instead of "no active session", it returns this ceremony.
 */
export const LedgerRecoverResult = z.object({
    /** Session ID that was recovered */
    sessionId: z.string(),
    /** Session start timestamp (epoch ms) */
    sessionStartTs: z.number().int().positive(),
    /** Handle expiry timestamp (epoch ms) — when the in-memory cursor closed */
    expiryTs: z.number().int().positive().nullable(),
    /** Expiry reason */
    expiryReason: z.enum(["idle-timeout", "daemon-restart", "explicit-end", "unknown"]),
    /** Timestamp of last heartbeat event in WAL (epoch ms) */
    lastHeartbeatTs: z.number().int().positive().nullable(),
    /** Timestamp of last event in WAL (epoch ms) */
    lastEventTs: z.number().int().positive().nullable(),
    /** Total event count captured before expiry */
    eventCount: z.number().int().min(0),
    /** Per-verb count summary */
    verbSummary: VerbSummary,
    /** Whether a ceremony was computed from the recovered events */
    ceremonyAvailable: z.boolean(),
    /** Ceremony payload (null if insufficient events for ceremony) */
    ceremony: z.record(z.unknown()).nullable(),
});
// =============================================================================
// session/reconcile params + result
// =============================================================================
/**
 * Parameters for session/reconcile IPC method.
 * Called when vreko_end fires on an expired or unknown session ID.
 * Routes to ledger/recover internally.
 */
export const SessionReconcileParams = z.object({
    /** Session ID that may be expired */
    sessionId: z.string(),
    /** Surface that is calling end */
    surfaceId: z.string(),
    /** Workspace fingerprint */
    workspaceFingerprint: z.string(),
});
export const SessionReconcileResult = z.object({
    /** Whether the session was found active, recovered from WAL, or not found at all */
    disposition: z.enum(["active", "recovered-from-wal", "not-found"]),
    /** Recovery result if disposition is "recovered-from-wal" */
    recovery: LedgerRecoverResult.nullable(),
});
