// ESM imports fixed for Node.js v22+
/**
 * Intelligence Parameter Schemas
 *
 * Intelligence-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/intelligence
 */
import { z } from "zod";
import { WarningSeverity } from "./primitives.js";
import { WorkspaceBase } from "./workspace-base.js";
// =============================================================================
// Intelligence Params
// =============================================================================
/**
 * Intelligence capture parameters
 * Gap Fields: Added outcome tracking for prevention metrics
 */
export const IntelligenceCaptureParams = WorkspaceBase.extend({
    /** Pattern content */
    content: z.string().min(1),
    /** Knowledge domain */
    domain: z
        .enum(["architecture", "testing", "documentation", "performance", "security", "workflow", "tooling"])
        .optional(),
    /** Pattern type */
    type: z.enum(["pattern", "anti-pattern", "best-practice", "constraint", "heuristic"]).optional(),
    /** Severity */
    severity: z.enum(["info", "warning", "error"]).optional(),
    /** Related pattern IDs */
    relatedTo: z.array(z.string()).optional(),
    /** Gap Fields: Outcome type for dashboard tracking (prevented/recovered/monitored) */
    outcome: z.enum(["prevented", "recovered", "monitored"]).optional(),
    /** Gap Fields: File categories involved (for risksPreventedContext) */
    fileCategories: z.array(z.string()).optional(),
    /** Gap Fields: Blast radius count for the decision */
    blastRadius: z.number().int().nonnegative().optional(),
    /** Gap Fields: File path for the event */
    filePath: z.string().optional(),
    /** Gap Fields: AI tool detected (cursor/copilot/claude) */
    aiTool: z.enum(["cursor", "copilot", "claude"]).optional(),
    /** Gap Fields: Risk level (high/medium/low) */
    risk: z.enum(["high", "medium", "low"]).optional(),
});
/**
 * Intelligence outcome parameters
 * Gap Fields: Extended with prevention tracking outcomes
 */
export const IntelligenceOutcomeParams = WorkspaceBase.extend({
    /** Pattern ID or Decision ID */
    patternId: z.string().min(1),
    /**
     * Outcome type
     * - resolved/regressed/ignored: Original pattern outcomes
     * - prevented/recovered/monitored: Gap Fields dashboard outcomes
     */
    outcome: z.enum(["resolved", "regressed", "ignored", "prevented", "recovered", "monitored"]),
    /** Notes */
    notes: z.string().optional(),
    /** Gap Fields: Whether decision was reverted within 5min (for accuracy calc) */
    revertedWithin5Min: z.boolean().optional(),
    /** Gap Fields: File categories involved */
    fileCategories: z.array(z.string()).optional(),
});
/**
 * Gap Fields: Decision outcome recording with 5min revert window tracking
 * Used for rolling accuracy calculation
 */
export const IntelligenceDecisionOutcomeParams = WorkspaceBase.extend({
    /** Unique decision ID */
    decisionId: z.string().min(1),
    /** Decision outcome */
    outcome: z.enum(["prevented", "recovered", "monitored", "reverted"]),
    /** Whether the decision was reverted within 5 minutes */
    revertedWithin5Min: z.boolean().optional(),
    /** File categories involved in the decision */
    fileCategories: z.array(z.string()).optional(),
    /** Human-readable action taken */
    action: z.string().optional(),
    /** Notes */
    notes: z.string().optional(),
});
// =============================================================================
// Intelligence Insights Params
// =============================================================================
/**
 * Get fragile files for a workspace
 */
export const IntelligenceFragileFilesParams = WorkspaceBase.extend({
    /** Minimum fragility score to include (0-1) */
    minScore: z.number().min(0).max(1).default(0.5),
    /** Maximum results */
    limit: z.number().int().min(1).max(50).default(20),
});
/**
 * Get co-change patterns for a workspace
 */
export const IntelligenceCoChangesParams = WorkspaceBase.extend({
    /** Minimum co-occurrence frequency to include (0-1) */
    minFrequency: z.number().min(0).max(1).default(0.5),
    /** Filter to patterns involving this file */
    filePath: z.string().optional(),
    /** Maximum results */
    limit: z.number().int().min(1).max(50).default(20),
});
/**
 * Get workspace intelligence summary
 * Gap Fields: Now includes prevention metrics
 */
export const IntelligenceSummaryParams = WorkspaceBase;
/**
 * Get active warnings for a workspace
 */
export const IntelligenceWarningsParams = WorkspaceBase.extend({
    /** Filter by minimum severity (uses WARNING_SEVERITY_ORDER for comparison) */
    minLevel: WarningSeverity.default("info"),
    /** Maximum results */
    limit: z.number().int().min(1).max(20).default(10),
});
/**
 * Get workspace health score (migrated from extension VitalsService)
 */
export const IntelligenceHealthParams = WorkspaceBase;
/**
 * Gap Fields: Get prevention metrics for dashboard
 */
export const IntelligencePreventionMetricsParams = WorkspaceBase.extend({
    /** Days to look back (default: 7) */
    days: z.number().int().min(1).max(30).default(7),
});
/**
 * Gap Fields: Get rolling accuracy metrics
 */
export const IntelligenceAccuracyMetricsParams = WorkspaceBase.extend({
    /** Weeks to look back (default: 8) */
    weeks: z.number().int().min(1).max(12).default(8),
});
/**
 * Get recurrence candidates for a workspace (Phase 4 - INTEL-11, INTEL-12, INTEL-13)
 */
export const IntelligenceRecurrenceCandidatesParams = WorkspaceBase.extend({
    /** Filter to specific files (omit to scan all files in window) */
    files: z.array(z.string()).optional(),
    /** Time window to query from the aggregate store */
    window: z.enum(["7d", "30d", "90d", "all"]).default("30d"),
    /** Minimum calibrated confidence floor (default: 0.55 = MIN_SURFACE_SCORE) */
    minConfidence: z.number().min(0).max(1).default(0.55),
    /** Maximum candidates to return */
    limit: z.number().int().min(1).max(20).default(10),
});
export const IntelligenceSeedParams = WorkspaceBase.extend({
    profile: z.any().optional(),
    fragileFiles: z.array(z.any()).optional(),
    coChangePairs: z.array(z.any()).optional(),
    temporalRiskWindows: z.array(z.any()).optional(),
    weightOverrides: z.any().optional(),
    lockedInsights: z.array(z.any()).optional(),
    scanCache: z.any().optional(),
});
export const IntelligenceUnlockParams = WorkspaceBase.extend({
    insightId: z.string(),
});
// =============================================================================
// Intelligence Snapshot (Intelligence Projection Architecture Phase 1)
// =============================================================================
/**
 * Parameters for the `intelligence/snapshot` IPC method.
 *
 * Returns the per-workspace IntelligenceSnapshot maintained by the
 * IntelligenceProjectionAggregator. See:
 *   packages/contracts/src/local-service/intelligence.ts
 */
export const IntelligenceSnapshotParams = WorkspaceBase;
/**
 * Parameters for the `intelligence/file-modified` IPC method.
 *
 * Records file modification observations to intelligence regardless of session context.
 * Session tracking is secondary - updates session if active, but never gates recording.
 */
export const IntelligenceFileModifiedParams = WorkspaceBase.extend({
    /** File path (relative to workspace root) */
    path: z.string().min(1),
    /** Lines changed */
    linesChanged: z.number().int().nonnegative().optional(),
    /** AI-attributed change */
    aiAttributed: z.boolean().optional(),
    /** Optional AI tool name if attributed */
    aiTool: z.enum(["cursor", "copilot", "claude", "windsurf", "burst-pattern"]).optional(),
});
/**
 * intelligence/ensureEmbeddingsReady  -  checks whether the per-workspace
 * intelligence service has loaded enough chunks/embeddings to answer queries.
 * Handler: apps/local-service/src/server/protocol.ts case "intelligence" then "ensureEmbeddingsReady"
 * Caller: packages/mcp/src/daemon/local-service-adapter.ts ensureEmbeddingsReadyViaDaemon()
 */
export const IntelligenceEnsureEmbeddingsReadyParams = z.object({
    workspace: z.string().optional(),
});
/**
 * intelligence/indexPatterns  -  parameters
 *
 * Requests the daemon to index or return indexed code patterns for the workspace.
 * Handler: apps/local-service/src/server/protocol.ts case "intelligence" → "indexPatterns"
 * Returns { patterns: [], total: 0 } stub (handler is a no-op stub, Phase 1 resolution is schema-only).
 * Callers: packages/mcp/src/daemon/intelligence-adapter.ts indexPatternsViaDaemon()
 *
 * Phantom resolved: method was routed but absent from MethodSchemas (blocked at isValidMethod).
 * Refs: deep-daemon-audit-2026-05-11.md Phase 1, implementation-prompt-2026-05-11.md Phase 1
 */
export const IntelligenceIndexPatternsParams = WorkspaceBase.extend({
    /** Factors or signals to index (optional, passed by MCP adapter).
     * Shape: Array<{ name: string; score: number; source: string; description?: string }>
     */
    factors: z
        .array(z.object({
        name: z.string(),
        score: z.number(),
        source: z.string(),
        description: z.string().optional(),
    }))
        .optional(),
});
/**
 * intelligence/indexPatterns  -  result
 */
export const IntelligenceIndexPatternsResult = z.object({
    /** Indexed patterns (currently an empty stub  -  full implementation deferred) */
    patterns: z.array(z.unknown()),
    /** Total pattern count */
    total: z.number().int().nonnegative(),
});
// =============================================================================
// Rules-File Projection IPC Params (Phase 2  -  intelligence-projection-architecture)
// =============================================================================
/**
 * projections/rules-file/status  -  query projection status for a workspace.
 */
export const ProjectionsRulesFileStatusParams = WorkspaceBase;
/**
 * projections/rules-file/enable  -  enable rules-file projection for a workspace.
 */
export const ProjectionsRulesFileEnableParams = WorkspaceBase;
/**
 * projections/rules-file/disable  -  disable rules-file projection for a workspace.
 */
export const ProjectionsRulesFileDisableParams = WorkspaceBase;
/**
 * projections/rules-file/dry-run  -  preview what would be written without writing.
 */
export const ProjectionsRulesFileDryRunParams = WorkspaceBase;
// =============================================================================
// VALID-04: Intelligence Result Schemas (decision-outcome, prevention-metrics,
// accuracy-metrics)
// =============================================================================
/**
 * Result for intelligence/decision-outcome
 * Shape derived from createIntelligenceService().decisionOutcome() return value.
 */
export const IntelligenceDecisionOutcomeResult = z.object({
    /** Whether the outcome was recorded */
    recorded: z.boolean(),
    /** The decision ID */
    decisionId: z.string(),
    /** The outcome type */
    outcome: z.string(),
    /** Whether the decision was reverted within 5 minutes */
    revertedWithin5Min: z.boolean().optional(),
    /** Impact on accuracy metric */
    accuracyImpact: z.enum(["reduced", "maintained"]),
    /** Optional notes */
    notes: z.string().optional(),
});
/**
 * Result for intelligence/prevention-metrics
 * Shape derived from createIntelligenceService().preventionMetrics() return value.
 */
export const IntelligencePreventionMetricsResult = z.object({
    /** Number of days in the window */
    days: z.number().int(),
    /** Number of risks prevented */
    risksPrevented: z.number().int(),
    /** Human-readable context about what was prevented */
    risksPreventedContext: z.string(),
    /** Daily prevented counts by day of week */
    dailyPrevented: z.array(z.object({
        day: z.string(),
        prevented: z.number().int(),
    })),
    /** Timeline events within the window */
    timelineEvents: z.array(z.object({
        hour: z.number().int(),
        type: z.enum(["recovery", "ai_detected", "snapshot"]),
        tool: z.string().optional(),
        file: z.string(),
        risk: z.string(),
        action: z.string(),
        blast: z.number().optional(),
    })),
    /** Total decisions in the window */
    totalDecisions: z.number().int(),
});
/**
 * Result for intelligence/accuracy-metrics
 * Shape derived from createIntelligenceService().accuracyMetrics() return value.
 */
export const IntelligenceAccuracyMetricsResult = z.object({
    /** Number of weeks in the window */
    weeks: z.number().int(),
    /** Weekly velocity data */
    velocity: z.array(z.object({
        week: z.string(),
        learnings: z.number().int(),
        accuracy: z.number().int(),
    })),
    /** Overall accuracy percentage (0-100) */
    overallAccuracy: z.number().int(),
    /** Session coherence percentage (0-100) */
    coherencePercent: z.number().int(),
    /** Ratio string e.g. "3 : 1" */
    preventedToRecoveredRatio: z.string(),
    /** Number of prevented decisions */
    preventedCount: z.number().int(),
    /** Number of recovered decisions */
    recoveredCount: z.number().int(),
    /** Total decisions in the window */
    totalDecisions: z.number().int(),
});
