/**
 * Primitive Schemas
 *
 * Base enum and primitive type definitions for the local-service protocol.
 *
 * @module @vreko/contracts/local-service/schemas/primitives
 */
import { z } from "zod";
// =============================================================================
// Protocol Primitives
// =============================================================================
/**
 * Protocol version schema (semantic versioning)
 *
 * Format: MAJOR.MINOR.PATCH (e.g., "1.0.0")
 */
export const ProtocolVersion = z.string().regex(/^\d+\.\d+\.\d+$/);
/**
 * Snapshot trigger type
 *
 * Indicates what action caused the snapshot to be created:
 * - save: Normal file save
 * - ai_burst: Rapid AI-generated changes detected
 * - manual: User explicitly requested snapshot
 * - timer: Automatic periodic snapshot
 * - pre_restore: Backup before restoring another snapshot
 * - external: Created by external tool/integration
 */
export const SnapshotTrigger = z.enum(["save", "ai_burst", "manual", "timer", "pre_restore", "external"]);
/**
 * Protection level
 *
 * Determines how aggressively to protect a file:
 * - watch: Monitor only, no interruptions
 * - warn: Show warnings but allow changes
 * - block: Prevent changes until user confirms
 */
export const ProtectionLevel = z.enum(["watch", "warn", "block"]);
/**
 * Risk level
 *
 * Assessment of change risk:
 * - low: Minor changes, low impact
 * - medium: Moderate changes, some risk
 * - high: Significant changes, considerable risk
 * - critical: Breaking changes, high risk
 */
export const RiskLevel = z.enum(["low", "medium", "high", "critical"]);
/**
 * Session state
 *
 * Current lifecycle state of a session:
 * - active: User actively working
 * - idle: No activity for a period
 * - ended: Session explicitly closed
 */
export const SessionState = z.enum(["active", "idle", "ended"]);
/**
 * User tier
 *
 * Subscription level:
 * - free: Basic features
 * - pro: Advanced features
 * - enterprise: Full features + support
 */
export const Tier = z.enum(["free", "pro", "enterprise"]);
// =============================================================================
// Type Primitives
// =============================================================================
/**
 * Learning type enum
 */
export const LearningType = z.enum([
    "pattern",
    "pitfall",
    "efficiency",
    "discovery",
    "workflow",
    "constraint",
    "preference",
]);
/**
 * Task intent classification
 */
export const TaskIntent = z.enum(["implement", "debug", "refactor", "review", "explore"]);
/**
 * Memory entry type
 */
export const MemoryEntryType = z.enum(["learning", "pattern", "violation", "context", "task", "session"]);
/**
 * Warning severity level with defined ordering.
 *
 * v2 FIX (M2): Severity ordering is explicit and machine-comparable.
 */
export const WarningSeverity = z.enum(["info", "warning", "error"]);
/**
 * Co-change pattern entry
 *
 * Two files that are frequently modified together, indicating a dependency
 * relationship that the developer should be aware of.
 *
 * v2 FIX (M1): `relationship` uses a known enum with `z.string()` fallback
 * for extensibility. New relationship types don't require schema changes.
 */
export const CoChangeRelationship = z
    .enum(["import_dependency", "test_coverage", "config_pair", "co_change_historical", "type_definition"])
    .or(z.string());
// =============================================================================
// Client Identity Primitives
// =============================================================================
/**
 * Client type enum
 *
 * Identifies the type of client connecting to the local-service daemon:
 * - vscode: VS Code extension via DaemonBridge
 * - mcp-stdio: MCP server running as CLI subprocess
 * - mcp-remote: MCP server on Fly.io
 * - cli: Direct CLI commands
 * - api: API backend server
 * - unknown: Pre-initialize or unidentified
 */
export const ClientType = z.enum(["vscode", "mcp-stdio", "mcp-remote", "cli", "api", "unknown"]);
