// ESM imports fixed for Node.js v22+
/**
 * Snapshot Parameter Schemas
 *
 * All snapshot-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/snapshot
 */
import { z } from "zod";
import { SavePathMetrics, ShouldCreateReason } from "./metrics.js";
import { RiskLevel, SnapshotTrigger } from "./primitives.js";
import { WorkspaceBase } from "./workspace-base.js";
// =============================================================================
// Snapshot Params (Original Local-Service Style)
// =============================================================================
/**
 * Snapshot create parameters
 */
export const SnapshotCreateParams = z.object({
    /** Absolute path to the file */
    filePath: z.string().min(1),
    /** File content to snapshot */
    content: z.string(),
    /** What triggered this snapshot */
    trigger: SnapshotTrigger,
    /** Additional snapshot metadata (optional) */
    metadata: z
        .object({
        /** AI tool that was active */
        aiToolDetected: z.string().optional(),
        /** Confidence score for AI detection (0-1) */
        aiConfidence: z.number().min(0).max(1).optional(),
        /** Risk level assessment */
        riskLevel: RiskLevel.optional(),
        /** Custom tags for organization */
        customTags: z.array(z.string()).optional(),
    })
        .optional(),
});
/**
 * Snapshot should-create parameters (fast-path decision)
 *
 * Used for save-path latency optimization. Target: P95 <50ms
 */
export const SnapshotShouldCreateParams = z.object({
    /** Absolute path to the file being saved */
    filePath: z.string().min(1),
    /** SHA-256 hash of the file content (optional, for deduplication) */
    contentHash: z.string().optional(),
    /** Last modification timestamp in milliseconds */
    lastModified: z.number().optional(),
    /** File size in bytes */
    byteSize: z.number().optional(),
});
/**
 * Snapshot should-create response
 */
export const SnapshotShouldCreateResponse = z.object({
    /** Whether a snapshot should be created */
    shouldCreate: z.boolean(),
    /** Reason for the decision */
    reason: ShouldCreateReason,
    /** Optional timing metrics for performance analysis */
    metrics: SavePathMetrics.optional(),
});
/**
 * Snapshot get parameters
 */
export const SnapshotGetParams = z.object({
    /** Snapshot ID to retrieve */
    snapshotId: z.string().min(1),
    /** Include full content in response (expensive) */
    includeContent: z.boolean().default(false),
});
/**
 * Snapshot list parameters
 */
export const SnapshotListParams = z.object({
    /** Filter by session ID (optional) */
    sessionId: z.string().min(1).optional(),
    /** Filter by file path (optional) */
    filePath: z.string().optional(),
    /** Filter by trigger types (optional) */
    trigger: z.array(SnapshotTrigger).optional(),
    /** Filter by created after timestamp (ISO 8601) */
    since: z.string().datetime().optional(),
    /** Filter by created before timestamp (ISO 8601) */
    until: z.string().datetime().optional(),
    /** Maximum number of snapshots to return */
    limit: z.number().int().min(1).max(200).default(50),
    /** Pagination cursor (opaque string) */
    cursor: z.string().optional(),
    /** Sort field */
    orderBy: z.enum(["createdAt", "filePath"]).default("createdAt"),
    /** Sort direction */
    orderDir: z.enum(["asc", "desc"]).default("desc"),
});
/**
 * Snapshot restore parameters
 */
export const SnapshotRestoreParams = z.object({
    /** Snapshot ID to restore */
    snapshotId: z.string().min(1),
    /** Target path (defaults to original path if omitted) */
    targetPath: z.string().optional(),
    /** Create backup snapshot before restoring */
    createBackup: z.boolean().default(true),
    /** Preview restore without writing (dry run) */
    dryRun: z.boolean().default(false),
});
/**
 * Snapshot diff parameters
 */
export const SnapshotDiffParams = z.object({
    /** Base snapshot ID for comparison */
    baseSnapshotId: z.string().min(1),
    /** Snapshot to compare against (defaults to current file if omitted) */
    compareSnapshotId: z.string().min(1).optional(),
    /** Number of context lines around changes */
    contextLines: z.number().int().min(0).max(10).default(3),
    /** Diff output format */
    format: z.enum(["unified", "split"]).default("unified"),
});
/**
 * Snapshot delete parameters
 */
export const SnapshotDeleteParams = z.object({
    /** Specific snapshot IDs to delete (optional) */
    snapshotIds: z.array(z.string().min(1)).optional(),
    /** Delete all snapshots older than timestamp (ISO 8601) (optional) */
    olderThan: z.string().datetime().optional(),
    /** Delete all snapshots in session (optional) */
    sessionId: z.string().min(1).optional(),
    /** Preview deletion without removing (dry run) */
    dryRun: z.boolean().default(false),
});
// =============================================================================
// Snapshot Extended Params (Daemon-style workspace-scoped)
// =============================================================================
/**
 * Snapshot create parameters (daemon-style, workspace-scoped)
 */
export const SnapshotCreateDaemonParams = WorkspaceBase.extend({
    /** Files to snapshot (relative paths) */
    files: z.array(z.string().min(1)).min(1),
    /** Reason for snapshot */
    reason: z.string().optional(),
    /** Snapshot trigger */
    trigger: z.enum(["manual", "mcp", "ai_assist", "session_end"]).optional(),
});
/**
 * Snapshot bulk delete parameters
 */
export const SnapshotBulkDeleteParams = WorkspaceBase.extend({
    /** Delete snapshots older than N days */
    olderThanDays: z.number().int().positive().optional(),
    /** Keep protected snapshots */
    keepProtected: z.boolean().default(true),
});
/**
 * Snapshot protect/unprotect parameters
 */
export const SnapshotProtectParams = WorkspaceBase.extend({
    /** Snapshot ID */
    snapshotId: z.string().min(1),
});
/**
 * Snapshot rename parameters
 */
export const SnapshotRenameParams = WorkspaceBase.extend({
    /** Snapshot ID */
    snapshotId: z.string().min(1),
    /** New name */
    newName: z.string().min(1),
});
/**
 * Get enriched snapshot list (snapshots + intelligence annotations)
 *
 * v2 FIX (M3): Cursor is opaque to consumers. Internally it's a
 * base64-encoded `{timestamp}:{snapshotId}` pair. Consumers must
 * not parse it  -  pass it back verbatim in subsequent requests.
 */
export const SnapshotListEnrichedParams = SnapshotListParams.extend({
    /** Include risk assessment per snapshot */
    includeRisk: z.boolean().default(true),
    /** Include AI attribution per snapshot */
    includeAttribution: z.boolean().default(true),
    /** Group by session cluster */
    groupBySessions: z.boolean().default(false),
});
