/**
 * Metrics Schemas
 *
 * Performance timing and metrics schemas for save path optimization.
 *
 * @module @vreko/contracts/local-service/schemas/metrics
 */
import { z } from "zod";
// =============================================================================
// Save Path Timing & Metrics (Phase 0.1 - Latency Instrumentation)
// =============================================================================
/**
 * A single timing span within a request
 * Used for detailed performance analysis of the save path
 */
export const TimingSpan = z.object({
    /** Name of the span (e.g., "ipc_receive", "service_dispatch", "decision") */
    name: z.string(),
    /** Start time in milliseconds relative to request start */
    startMs: z.number(),
    /** End time in milliseconds relative to request start */
    endMs: z.number(),
});
/**
 * Complete metrics for a save path operation
 * Tracks end-to-end timing with breakdown by span
 */
export const SavePathMetrics = z.object({
    /** Unique identifier for this request */
    requestId: z.string(),
    /** Total time from request receive to response send */
    totalMs: z.number(),
    /** Breakdown of time spent in each phase */
    spans: z.array(TimingSpan),
    /** Whether a snapshot was actually created */
    snapshotCreated: z.boolean(),
});
/**
 * Reason why a snapshot should or should not be created
 *
 * - no_previous: No previous snapshot exists for this file
 * - hash_changed: Content hash differs from last snapshot
 * - time_threshold: Time since last snapshot exceeds threshold
 * - size_threshold: File size change exceeds threshold
 * - no_change: No changes detected, skip snapshot
 * - cooldown: Within cooldown period, skip snapshot
 */
export const ShouldCreateReason = z.enum([
    "no_previous",
    "hash_changed",
    "time_threshold",
    "size_threshold",
    "no_change",
    "cooldown",
]);
