/**
 * Baseline Zod Schemas
 *
 * Phase 5-A: BaselineRecord Schema + Storage
 * Phase 6-A: Uses enhanced AI config types from ai-config.ts
 *
 * @module @vreko/contracts/local-service/schemas/baseline
 */
import { z } from "zod";
// =============================================================================
// Baseline Entity Schemas
// =============================================================================
/**
 * File record in baseline
 */
export const FileRecord = z.object({
    path: z.string(),
    category: z.enum(["config", "source", "test", "build", "docs", "other"]),
    domain: z.string(),
    sizeBytes: z.number(),
    lineCount: z.number(),
    extension: z.string(),
});
/**
 * Churn record for a file
 */
export const ChurnRecord = z.object({
    filePath: z.string(),
    changes30d: z.number(),
    changes90d: z.number(),
    lastChangedAt: z.number(),
    uniqueAuthors: z.number(),
});
/**
 * Co-change cluster
 */
export const CoChangeCluster = z.object({
    files: z.array(z.string()),
    coOccurrenceRate: z.number().min(0).max(1),
    sampleSize: z.number(),
});
/**
 * Fragile file score
 */
export const FragileFileRecord = z.object({
    path: z.string(),
    compositeScore: z.number().min(0).max(100),
    churnScore: z.number(),
    blastRadiusScore: z.number(),
    rollbackScore: z.number(),
    dependentCount: z.number(),
    rank: z.number(),
});
/**
 * Domain health score
 */
export const DomainHealthScore = z.object({
    domain: z.string(),
    score: z.number().min(0).max(100),
    fileCount: z.number(),
    avgChurn: z.number(),
    fragileFileCount: z.number(),
    trend: z.enum(["improving", "stable", "degrading", "unknown"]),
    trendComputedAt: z.number().nullable(),
});
/**
 * Baseline narrative
 */
export const BaselineNarrative = z.object({
    domainSummaries: z.record(z.string()),
    topRisks: z.array(z.object({
        file: z.string(),
        reason: z.string(),
        severity: z.enum(["high", "medium"]),
    })),
    agentContextTemplate: z.string(),
});
/**
 * Dependency graph
 */
export const DependencyGraph = z.object({
    nodes: z.array(z.string()),
    edges: z.array(z.object({
        from: z.string(),
        to: z.string(),
    })),
    blastRadii: z.record(z.number()),
});
// =============================================================================
// Full Baseline Record (references ai-config types)
// =============================================================================
/**
 * Full baseline record - uses lazy imports to avoid circular dependencies
 * The actual ParsedAIConfig and AIConfigConflict types come from ai-config.ts
 */
export const BaselineRecord = z.object({
    workspacePath: z.string(),
    computedAt: z.number(),
    version: z.string(),
    // Tier 1: Structural
    fileInventory: z.array(FileRecord),
    domainMap: z.record(z.array(z.string())),
    totalFiles: z.number(),
    totalLines: z.number(),
    // Tier 2: Historical
    churnRates: z.record(ChurnRecord),
    coChangeClusters: z.array(CoChangeCluster),
    rollbackHotspots: z.array(z.string()),
    // Tier 3: Computed scores
    fragileFiles: z.array(FragileFileRecord),
    domainHealthScores: z.array(DomainHealthScore),
    overallHealthScore: z.number().min(0).max(100),
    // Dependency graph
    dependencyGraph: DependencyGraph,
    // AI config files (imported from ai-config.ts for enhanced types)
    aiConfigFiles: z.array(z.any()), // ParsedAIConfig - use z.any() to avoid circular import
    aiConfigConflicts: z.array(z.any()), // AIConfigConflict - use z.any() to avoid circular import
    // AI synthesis
    narrative: BaselineNarrative.nullable(),
    narrativeComputedAt: z.number().nullable(),
});
// =============================================================================
// Baseline Status
// =============================================================================
export const BaselineStatus = z.enum(["ready", "stale", "computing", "not_computed"]);
export const BaselineComputeProgress = z.object({
    status: BaselineStatus,
    progress: z.number().min(0).max(100),
    stage: z.string().optional(),
    error: z.string().optional(),
});
// =============================================================================
// Method Params
// =============================================================================
/**
 * baseline/get params
 */
export const BaselineGetParams = z.object({
    workspace: z.string(),
});
/**
 * baseline/compute params
 */
export const BaselineComputeParams = z.object({
    workspace: z.string(),
});
/**
 * baseline/status params
 */
export const BaselineStatusParams = z.object({
    workspace: z.string(),
});
/**
 * baseline/invalidate params
 */
export const BaselineInvalidateParams = z.object({
    workspace: z.string(),
});
/**
 * baseline/update params (internal use)
 */
export const BaselineUpdateParams = z.object({
    workspace: z.string(),
    record: BaselineRecord,
});
// =============================================================================
// Baseline Result Schemas (VALID-T Batch 3)
// =============================================================================
export const BaselineComputeResult = z.object({
    jobId: z.string(),
});
export const BaselineStatusResult = z.object({
    status: z.enum(["ready", "stale", "computing", "not_computed"]),
    progress: z.number().int().min(0).max(100),
    stage: z.string().optional(),
    error: z.string().optional(),
});
export const BaselineInvalidateResult = z.void();
