// ESM imports fixed for Node.js v22+
/**
 * Task Coordinator Parameter Schemas
 *
 * Task coordinator related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/task
 */
import { z } from "zod";
import { TaskIntent } from "./primitives.js";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Task start parameters
 */
export const TaskStartParams = WorkspaceBase.extend({
    /** Task summary/description */
    task: z.string().min(1),
    /** Files involved in the task */
    files: z.array(z.string()).optional(),
    /** Keywords for context matching */
    keywords: z.array(z.string()).optional(),
    /** Task intent classification */
    intent: TaskIntent.optional(),
});
/**
 * Task progress parameters
 */
export const TaskProgressParams = WorkspaceBase.extend({
    /** Progress message */
    message: z.string().min(1),
    /** Files modified in this progress */
    filesModified: z.array(z.string()).optional(),
    /** Partial completion percentage */
    completionPercent: z.number().min(0).max(100).optional(),
});
/**
 * Task end parameters
 */
export const TaskEndParams = WorkspaceBase.extend({
    /**
     * Free-text outcome. Do NOT constrain to enum  -  snap_end promises free-text paragraphs.
     */
    outcome: z.string().min(1).max(2000),
    /** Outcome notes */
    notes: z.string().optional(),
    /** Learnings captured during task */
    learnings: z.array(z.string()).optional(),
});
/**
 * Task status parameters
 */
export const TaskStatusParams = WorkspaceBase;
/**
 * Task context parameters
 */
export const TaskContextParams = WorkspaceBase;
// =============================================================================
// Task Result Schemas (VALID-T Batch 4)
// =============================================================================
export const TaskProgressResult = z.object({
    recorded: z.boolean(),
    taskId: z.string().nullable(),
});
export const TaskEndResult = z.object({
    ended: z.boolean(),
    taskId: z.string().nullable(),
    durationMs: z.number().nonnegative(),
});
