/**
 * Detection Parameter Schemas
 *
 * Detection and analysis related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/detection
 */
import { z } from "zod";
/**
 * Detection check parameters
 */
export const DetectionCheckParams = z.object({
    /** File path being checked */
    filePath: z.string().min(1),
    /** Current file content */
    content: z.string(),
    /** Previous content for comparison (optional) */
    previousContent: z.string().optional(),
    /** Additional metadata (optional) */
    metadata: z
        .object({
        /** Editor information string */
        editorInfo: z.string().optional(),
        /** Timestamp in milliseconds since epoch */
        timestamp: z.number().int().positive().optional(),
    })
        .optional(),
});
/**
 * Analyze risk parameters (PRO tier)
 */
export const AnalyzeRiskParams = z.object({
    /** Unified diff string to analyze */
    diff: z.string(),
    /** Context about the change */
    context: z.object({
        /** File path being changed */
        filePath: z.string(),
        /** Programming language (optional) */
        language: z.string().optional(),
        /** Project type (e.g., "web", "mobile", "backend") (optional) */
        projectType: z.string().optional(),
    }),
});
/**
 * Analyze grouping parameters (PRO tier)
 */
export const AnalyzeGroupingParams = z.object({
    /** Snapshot IDs to analyze for grouping */
    snapshotIds: z.array(z.string().uuid()).min(1),
});
/**
 * Sync trigger parameters (PRO tier)
 */
export const SyncTriggerParams = z.object({
    /** Sync direction */
    direction: z.enum(["push", "pull", "both"]).default("both"),
    /** Specific snapshot IDs to sync (optional, syncs all if omitted) */
    snapshotIds: z.array(z.string().uuid()).optional(),
});
