// ESM imports fixed for Node.js v22+
/**
 * Refactoring Intelligence Parameter Schemas
 *
 * Refactoring intelligence related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/refactoring
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Refactoring assessment parameters
 */
export const RefactoringAssessParams = WorkspaceBase.extend({
    /** Optional: specific component ID to assess */
    targetComponentId: z.string().optional(),
    /** Optional: minimum test coverage threshold (0.0-1.0) */
    minTestCoverage: z.number().min(0).max(1).optional(),
    /** Optional: maximum dependency count threshold */
    maxDependencyCount: z.number().int().positive().optional(),
    /** Optional: minimum confidence threshold (0.0-1.0) */
    minConfidence: z.number().min(0).max(1).optional(),
});
/**
 * Refactoring report parameters
 */
export const RefactoringReportParams = WorkspaceBase.extend({
    /** Include all candidates in report (not just recommendations) */
    includeAllCandidates: z.boolean().optional(),
});
/**
 * Get top recommendations parameters
 */
export const RefactoringGetTopRecommendationsParams = WorkspaceBase.extend({
    /** Maximum number of recommendations to return */
    limit: z.number().int().positive().optional(),
    /** Minimum priority level to include */
    minPriority: z.enum(["critical", "high", "medium", "low"]).optional(),
});
/**
 * Get component analysis parameters
 */
export const RefactoringGetComponentAnalysisParams = WorkspaceBase.extend({
    /** Component ID to analyze */
    componentId: z.string(),
});
/**
 * Set manual gate parameters
 */
export const RefactoringSetGateParams = WorkspaceBase.extend({
    /** Component ID to set gate for */
    componentId: z.string(),
    /** Gate to set */
    gate: z.enum(["migrationPlan", "rollbackStrategy", "ownerAssigned", "stakeholderSignoff"]),
    /** Gate status */
    status: z.enum(["pass", "fail", "warn", "pending"]),
});
/**
 * Get gates parameters
 */
export const RefactoringGetGatesParams = WorkspaceBase.extend({
    /** Component ID to get gates for */
    componentId: z.string(),
});
/**
 * Filter recommendations parameters
 */
export const RefactoringFilterRecommendationsParams = WorkspaceBase.extend({
    /** Filter by actions */
    actions: z.array(z.enum(["refactor-now", "schedule", "defer", "monitor", "reject"])).optional(),
    /** Filter by priorities */
    priorities: z.array(z.enum(["critical", "high", "medium", "low"])).optional(),
    /** Minimum confidence threshold */
    minConfidence: z.number().min(0).max(1).optional(),
});
/**
 * Get stats parameters
 */
export const RefactoringGetStatsParams = WorkspaceBase;
