// ESM imports fixed for Node.js v22+
/**
 * Watch Parameter Schemas
 *
 * File watcher related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/watch
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Watch subscribe parameters
 */
export const WatchSubscribeParams = WorkspaceBase.extend({
    /** Glob patterns to watch */
    patterns: z.array(z.string()).optional(),
});
/**
 * Watch unsubscribe parameters
 */
export const WatchUnsubscribeParams = WorkspaceBase;
/**
 * File changed notification parameters
 */
export const WatchFileChangedParams = WorkspaceBase.extend({
    /** File that changed */
    file: z.string().min(1),
    /** Timestamp of change */
    timestamp: z.number().int().positive(),
});
// =============================================================================
// Watch Result Schemas (VALID-T Batch 2)
// =============================================================================
export const WatchSubscribeResult = z.object({
    subscribed: z.literal(true),
    patterns: z.array(z.string()),
});
export const WatchUnsubscribeResult = z.object({
    unsubscribed: z.literal(true),
});
export const WatchFileChangedResult = z.object({
    received: z.literal(true),
    file: z.string(),
    timestamp: z.number(),
    ignored: z.literal(true).optional(),
});
