/**
 * Vreko Local Service Protocol - Core Protocol Types
 *
 * JSON-RPC 2.0 base types, method definitions, and error codes for the
 * Vreko local coordination service (vrekod).
 *
 * @module @vreko/contracts/local-service/protocol
 *
 * @example
 * ```typescript
 * import { JsonRpcRequest, LocalServiceMethod, ProtocolErrorCode } from '@vreko/contracts/local-service';
 *
 * const request: JsonRpcRequest = {
 *   jsonrpc: "2.0",
 *   id: "req-1",
 *   method: "snapshot/create",
 *   params: { filePath: "/path/to/file.ts", content: "...", trigger: "save" }
 * };
 * ```
 */
// =============================================================================
// Protocol Version
// =============================================================================
/**
 * Current protocol version (semantic versioning)
 */
export const PROTOCOL_VERSION = "1.0.0";
// =============================================================================
// ZOD SCHEMAS FOR RUNTIME VALIDATION (P1-D: IPC Parse Boundary)
// =============================================================================
import { z } from "zod";
/**
 * JSON-RPC 2.0 request schema for runtime validation
 */
export const JsonRpcRequestSchema = z.object({
    jsonrpc: z.literal("2.0"),
    id: z.union([z.string(), z.number()]),
    method: z.string(),
    params: z.unknown().optional(),
});
/**
 * JSON-RPC 2.0 error object schema
 */
export const JsonRpcErrorSchema = z.object({
    code: z.number(),
    message: z.string(),
    data: z.unknown().optional(),
});
/**
 * JSON-RPC 2.0 success response schema
 */
const JsonRpcSuccessResponseSchema = z.object({
    jsonrpc: z.literal("2.0"),
    id: z.union([z.string(), z.number()]).optional(),
    result: z.unknown(),
});
/**
 * JSON-RPC 2.0 error response schema
 */
const JsonRpcErrorResponseSchema = z.object({
    jsonrpc: z.literal("2.0"),
    id: z.union([z.string(), z.number()]).optional(),
    error: JsonRpcErrorSchema,
});
/**
 * JSON-RPC 2.0 response schema (union of success and error)
 */
export const JsonRpcResponseSchema = z.union([JsonRpcSuccessResponseSchema, JsonRpcErrorResponseSchema]);
/**
 * JSON-RPC 2.0 notification schema (no id field)
 */
export const JsonRpcNotificationSchema = z.object({
    jsonrpc: z.literal("2.0"),
    method: z.string(),
    params: z.unknown().optional(),
});
/**
 * Unified JSON-RPC message schema (request, response, or notification)
 * Used for IPC parse boundary validation (P1-D requirement)
 */
export const JsonRpcMessageSchema = z.union([JsonRpcRequestSchema, JsonRpcResponseSchema, JsonRpcNotificationSchema]);
/**
 * Type guards for runtime validation
 */
export function isJsonRpcRequest(message) {
    const result = JsonRpcRequestSchema.safeParse(message);
    return result.success;
}
export function isJsonRpcResponse(message) {
    const result = JsonRpcResponseSchema.safeParse(message);
    return result.success;
}
export function isJsonRpcNotification(message) {
    const result = JsonRpcNotificationSchema.safeParse(message);
    return result.success;
}
// =============================================================================
// Error Codes
// =============================================================================
/**
 * Protocol error codes
 *
 * Categories:
 * - -32xxx: JSON-RPC 2.0 standard errors
 * - 1xxx: Authentication and tier errors
 * - 2xxx: Session errors
 * - 3xxx: Snapshot errors
 * - 4xxx: File system errors
 */
export var ProtocolErrorCode;
(function (ProtocolErrorCode) {
    // JSON-RPC 2.0 Standard Errors (-32700 to -32600)
    /** Invalid JSON was received */
    ProtocolErrorCode[ProtocolErrorCode["ParseError"] = -32700] = "ParseError";
    /** The JSON sent is not a valid JSON-RPC 2.0 request */
    ProtocolErrorCode[ProtocolErrorCode["InvalidRequest"] = -32600] = "InvalidRequest";
    /** The method does not exist */
    ProtocolErrorCode[ProtocolErrorCode["MethodNotFound"] = -32601] = "MethodNotFound";
    /** Invalid method parameters */
    ProtocolErrorCode[ProtocolErrorCode["InvalidParams"] = -32602] = "InvalidParams";
    /** Internal service error */
    ProtocolErrorCode[ProtocolErrorCode["InternalError"] = -32603] = "InternalError";
    // Custom Server Errors (-32000 to -32099)
    /** Generic server error */
    ProtocolErrorCode[ProtocolErrorCode["ServerError"] = -32000] = "ServerError";
    /** Client sent request before initialize */
    ProtocolErrorCode[ProtocolErrorCode["NotInitialized"] = -32001] = "NotInitialized";
    /** Client sent initialize twice */
    ProtocolErrorCode[ProtocolErrorCode["AlreadyInitialized"] = -32002] = "AlreadyInitialized";
    /** Service is shutting down */
    ProtocolErrorCode[ProtocolErrorCode["ShuttingDown"] = -32003] = "ShuttingDown";
    // Authentication & Authorization (1000-1999)
    /** Authentication required for this method */
    ProtocolErrorCode[ProtocolErrorCode["NotAuthenticated"] = 1000] = "NotAuthenticated";
    /** PRO tier required for this method */
    ProtocolErrorCode[ProtocolErrorCode["TierRequired"] = 1001] = "TierRequired";
    /** Cannot reach api.vreko.dev */
    ProtocolErrorCode[ProtocolErrorCode["ApiUnavailable"] = 1002] = "ApiUnavailable";
    /** Storage or API quota exceeded */
    ProtocolErrorCode[ProtocolErrorCode["QuotaExceeded"] = 1003] = "QuotaExceeded";
    // Workspace Errors (1500-1999)
    /** Workspace not found or not initialized */
    ProtocolErrorCode[ProtocolErrorCode["WorkspaceNotFound"] = 1500] = "WorkspaceNotFound";
    /** Workspace already exists */
    ProtocolErrorCode[ProtocolErrorCode["WorkspaceAlreadyExists"] = 1501] = "WorkspaceAlreadyExists";
    // Session Errors (2000-2999)
    /** Session does not exist */
    ProtocolErrorCode[ProtocolErrorCode["SessionNotFound"] = 2000] = "SessionNotFound";
    /** Session has already ended */
    ProtocolErrorCode[ProtocolErrorCode["SessionEnded"] = 2001] = "SessionEnded";
    // Snapshot Errors (3000-3999)
    /** Snapshot does not exist */
    ProtocolErrorCode[ProtocolErrorCode["SnapshotNotFound"] = 3000] = "SnapshotNotFound";
    /** Content integrity check failed */
    ProtocolErrorCode[ProtocolErrorCode["ContentHashMismatch"] = 3001] = "ContentHashMismatch";
    /** Could not write restored file */
    ProtocolErrorCode[ProtocolErrorCode["RestoreFailed"] = 3002] = "RestoreFailed";
    // File System Errors (4000-4999)
    /** File does not exist */
    ProtocolErrorCode[ProtocolErrorCode["FileNotFound"] = 4000] = "FileNotFound";
    /** Cannot read/write file */
    ProtocolErrorCode[ProtocolErrorCode["FileAccessDenied"] = 4001] = "FileAccessDenied";
    /** Path is outside allowed directories */
    ProtocolErrorCode[ProtocolErrorCode["InvalidPath"] = 4002] = "InvalidPath";
    // Learning Errors (5000-5999)
    /** Learning not found */
    ProtocolErrorCode[ProtocolErrorCode["LearningNotFound"] = 5000] = "LearningNotFound";
    /** Learning evaluation failed */
    ProtocolErrorCode[ProtocolErrorCode["LearningEvaluationFailed"] = 5001] = "LearningEvaluationFailed";
    // Sync Errors (6000-6999)
    /** Sync worker not available */
    ProtocolErrorCode[ProtocolErrorCode["SyncUnavailable"] = 6000] = "SyncUnavailable";
    /** Sync authentication required */
    ProtocolErrorCode[ProtocolErrorCode["SyncAuthRequired"] = 6001] = "SyncAuthRequired";
    // Validation Errors (7000-7999)
    /** Validation timed out */
    ProtocolErrorCode[ProtocolErrorCode["ValidationTimeout"] = 7000] = "ValidationTimeout";
    // Intelligence Errors (8000-8999)
    /** Intelligence service not available */
    ProtocolErrorCode[ProtocolErrorCode["IntelligenceUnavailable"] = 8000] = "IntelligenceUnavailable";
    /** Pattern not found */
    ProtocolErrorCode[ProtocolErrorCode["PatternNotFound"] = 8001] = "PatternNotFound";
})(ProtocolErrorCode || (ProtocolErrorCode = {}));
/**
 * Error code to message mapping
 */
export const ERROR_MESSAGES = {
    [ProtocolErrorCode.ParseError]: "Invalid JSON",
    [ProtocolErrorCode.InvalidRequest]: "Invalid JSON-RPC request",
    [ProtocolErrorCode.MethodNotFound]: "Method does not exist",
    [ProtocolErrorCode.InvalidParams]: "Invalid method parameters",
    [ProtocolErrorCode.InternalError]: "Internal service error",
    [ProtocolErrorCode.ServerError]: "Server error",
    [ProtocolErrorCode.NotInitialized]: "Client must call initialize before other methods",
    [ProtocolErrorCode.AlreadyInitialized]: "Client has already called initialize",
    [ProtocolErrorCode.ShuttingDown]: "Service is shutting down",
    [ProtocolErrorCode.NotAuthenticated]: "Authentication required for this method",
    [ProtocolErrorCode.TierRequired]: "PRO tier required for this method",
    [ProtocolErrorCode.ApiUnavailable]: "Cannot reach api.vreko.dev",
    [ProtocolErrorCode.QuotaExceeded]: "Storage or API quota exceeded",
    [ProtocolErrorCode.SessionNotFound]: "Session does not exist",
    [ProtocolErrorCode.SessionEnded]: "Session has already ended",
    [ProtocolErrorCode.SnapshotNotFound]: "Snapshot does not exist",
    [ProtocolErrorCode.ContentHashMismatch]: "Content integrity check failed",
    [ProtocolErrorCode.RestoreFailed]: "Could not write restored file",
    [ProtocolErrorCode.FileNotFound]: "File does not exist",
    [ProtocolErrorCode.FileAccessDenied]: "Cannot read/write file",
    [ProtocolErrorCode.InvalidPath]: "Path is outside allowed directories",
    [ProtocolErrorCode.WorkspaceNotFound]: "Workspace not found or not initialized",
    [ProtocolErrorCode.WorkspaceAlreadyExists]: "Workspace already exists",
    [ProtocolErrorCode.LearningNotFound]: "Learning not found",
    [ProtocolErrorCode.LearningEvaluationFailed]: "Learning evaluation failed",
    [ProtocolErrorCode.SyncUnavailable]: "Sync worker not available",
    [ProtocolErrorCode.SyncAuthRequired]: "Sync authentication required",
    [ProtocolErrorCode.ValidationTimeout]: "Validation timed out",
    [ProtocolErrorCode.IntelligenceUnavailable]: "Intelligence service not available",
    [ProtocolErrorCode.PatternNotFound]: "Pattern not found",
};
