/**
 * Digest Service Schemas
 *
 * Parameter schemas for the Digest service (Pioneer Dashboard).
 *
 * @module @vreko/contracts/local-service/schemas/digest
 */
import { z } from "zod";
// =============================================================================
// Digest Compute Params
// =============================================================================
/**
 * Parameters for digest/compute method
 */
export const DigestComputeParams = z.object({
    /** Workspace root path */
    workspace: z.string().min(1).describe("Workspace root path"),
    /** Force refresh cache */
    force: z.boolean().optional().default(false).describe("Force refresh cache"),
});
// =============================================================================
// Digest Invalidate Params
// =============================================================================
/**
 * Parameters for digest/invalidate method
 */
export const DigestInvalidateParams = z.object({
    /** Workspace root path */
    workspace: z.string().min(1).describe("Workspace root path"),
});
// =============================================================================
// Digest Stats Params
// =============================================================================
/**
 * Parameters for digest/stats method
 */
export const DigestStatsParams = z.object({});
