// ESM imports fixed for Node.js v22+
/**
 * Momentum Parameter Schemas
 *
 * Momentum-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/momentum
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Momentum refresh parameters
 */
export const MomentumRefreshParams = WorkspaceBase.extend({
    /** Compare against this commit (default HEAD~10) */
    since: z.string().optional(),
    /** Force full re-fit */
    full: z.boolean().optional(),
});
/**
 * Momentum score parameters
 */
export const MomentumScoreParams = WorkspaceBase.extend({
    /** File path to score */
    filePath: z.string().min(1),
});
/**
 * Momentum sync parameters
 */
export const MomentumSyncParams = WorkspaceBase.extend({
    /** Quick mode (git + AST only) */
    quick: z.boolean().optional(),
});
/**
 * Momentum status parameters
 */
export const MomentumStatusParams = WorkspaceBase;
// =============================================================================
// Momentum Result Schemas (VALID-T Batch 3)
// =============================================================================
export const MomentumRefreshResult = z.object({
    refreshed: z.literal(true),
    since: z.string(),
    full: z.boolean(),
    scores: z.record(z.unknown()),
    timestamp: z.number(),
});
export const MomentumScoreResult = z.object({
    filePath: z.string(),
    score: z.number().min(0).max(1),
    factors: z.object({
        changeFrequency: z.number(),
        complexity: z.number(),
        recency: z.number(),
    }),
    timestamp: z.number(),
});
export const MomentumSyncResult = z.object({
    synced: z.literal(true),
    quick: z.boolean(),
    filesAnalyzed: z.number().int().nonnegative(),
    timestamp: z.number(),
});
export const MomentumStatusResult = z.object({
    active: z.boolean(),
    lastSync: z.string().nullable(),
    fileCount: z.number().int().nonnegative(),
    averageScore: z.number(),
});
