// ESM imports fixed for Node.js v22+
/**
 * Protection Parameter Schemas
 *
 * All protection-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/protection
 */
import { z } from "zod";
import { ProtectionLevel } from "./primitives.js";
import { WorkspaceBase } from "./workspace-base.js";
// =============================================================================
// Protection Params (Original Local-Service Style)
// =============================================================================
/**
 * Protection evaluate parameters
 */
export const ProtectionEvaluateParams = z.object({
    /** File path to evaluate */
    filePath: z.string().min(1),
    /** Current file content (optional, reads from disk if omitted) */
    content: z.string().optional(),
    /** Additional context for evaluation (optional) */
    context: z
        .object({
        /** Number of recent changes to the file */
        recentChanges: z.number().int().nonnegative().optional(),
        /** Milliseconds since last save */
        timeSinceLastSave: z.number().int().nonnegative().optional(),
        /** Whether an AI tool is currently active */
        aiToolActive: z.boolean().optional(),
    })
        .optional(),
});
/**
 * Protection levels parameters
 */
export const ProtectionLevelsParams = z.object({
    /** File paths to get protection levels for */
    filePaths: z.array(z.string().min(1)).min(1).max(100),
});
/**
 * Protection set parameters
 */
export const ProtectionSetParams = z.object({
    /** File path to set protection for */
    filePath: z.string().min(1),
    /** Protection level to set ("auto" to reset to automatic) */
    level: z.enum(["watch", "warn", "block", "auto"]),
    /** Scope of the protection rule */
    scope: z.enum(["file", "directory", "pattern"]).default("file"),
    /** Pattern for pattern-based rules (glob syntax) (optional) */
    pattern: z.string().optional(),
});
// =============================================================================
// Protection Params (Daemon-style)
// =============================================================================
/**
 * Protection get level parameters (daemon-style)
 */
export const ProtectionGetLevelParams = WorkspaceBase.extend({
    /** File path */
    filePath: z.string().min(1),
});
/**
 * Protection set level parameters (daemon-style)
 */
export const ProtectionSetLevelParams = WorkspaceBase.extend({
    /** File path */
    filePath: z.string().min(1),
    /** Protection level */
    level: ProtectionLevel,
    /** Reason for setting level */
    reason: z.string().optional(),
});
/**
 * Protection list parameters (daemon-style)
 */
export const ProtectionListParams = WorkspaceBase.extend({
    /** Filter by level */
    level: ProtectionLevel.optional(),
    /** Max results */
    limit: z.number().int().min(1).max(500).optional(),
});
// =============================================================================
// VALID-04: Protection Result Schemas
// =============================================================================
/**
 * Result for protection/evaluate
 * Shape derived from createProtectionService().evaluate() return value.
 */
export const ProtectionEvaluateResult = z.object({
    /** Protection level assigned */
    level: ProtectionLevel,
    /** Whether protection was assigned automatically */
    automatic: z.boolean(),
    /** Source of the protection decision */
    source: z.string(),
    /** Confidence score (0-1) */
    confidence: z.number().min(0).max(1),
    /** Risk score (0-100) */
    riskScore: z.number().min(0).max(100),
    /** Recommended action */
    recommendation: z.string(),
    /** Contributing risk factors */
    factors: z.array(z.object({
        name: z.string(),
        score: z.number(),
        description: z.string(),
        source: z.string(),
        suggestion: z.string().optional(),
    })),
});
/**
 * Result for protection/levels
 * Shape derived from createProtectionService().levels() return value.
 */
export const ProtectionLevelsResult = z.object({
    /** Map of level name to level descriptor */
    levels: z.record(z.object({
        description: z.string(),
        automatic: z.boolean(),
    })),
});
/**
 * Result for protection/set
 * Shape derived from createProtectionService().set() return value.
 */
export const ProtectionSetResult = z.object({
    /** Whether the protection level was set successfully */
    success: z.boolean(),
});
/**
 * Result for protection/get-level (optional method — falls through to notImpl if absent)
 * Conservative schema: level field, optional.
 */
export const ProtectionGetLevelResult = z.object({
    /** Protection level, if retrievable */
    level: ProtectionLevel.optional(),
});
/**
 * Result for protection/set-level (optional method — falls through to notImpl if absent)
 */
export const ProtectionSetLevelResult = z.object({
    /** Whether the level was set */
    success: z.boolean(),
});
/**
 * Result for protection/list-daemon (optional method — falls through to notImpl if absent)
 */
export const ProtectionListDaemonResult = z.array(z.object({
    filePath: z.string(),
    level: ProtectionLevel,
}));
