// ESM imports fixed for Node.js v22+
/**
 * Context Parameter Schemas
 *
 * Context-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/context
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Get context parameters
 */
export const ContextGetParams = WorkspaceBase.extend({
    /** Task description */
    task: z.string().min(1),
    /** Files involved */
    files: z.array(z.string()).optional(),
    /** Keywords for context matching */
    keywords: z.array(z.string()).optional(),
});
/**
 * Validate context parameters
 */
export const ContextValidateParams = WorkspaceBase;
/**
 * Check patterns parameters
 */
export const ContextCheckPatternsParams = WorkspaceBase.extend({
    /** Code to check */
    code: z.string(),
    /** File path */
    filePath: z.string().min(1),
});
// =============================================================================
// Context Result Schemas (VALID-T Batch 2)
// =============================================================================
export const ContextValidateResult = z.object({
    valid: z.boolean(),
    contextPath: z.string(),
});
export const ContextCheckPatternsResult = z.object({
    passed: z.boolean(),
    totalIssues: z.number().int().nonnegative().optional(),
    focusPoints: z.array(z.unknown()).optional(),
    violations: z.array(z.string()).optional(),
    suggestions: z.array(z.string()).optional(),
});
