// ESM imports fixed for Node.js v22+
/**
 * MCP Coordination Parameter Schemas
 *
 * MCP coordination related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/mcp
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Snapshot created notification parameters
 */
export const MCPSnapshotCreatedParams = WorkspaceBase.extend({
    /** Snapshot ID */
    id: z.string().min(1),
    /** File path */
    filePath: z.string().optional(),
    /** Trigger type */
    trigger: z.enum(["manual", "auto", "ai-detection"]).optional(),
    /** Source surface */
    source: z.enum(["mcp", "cli", "extension"]).optional(),
});
// =============================================================================
// MCP Result Schemas (VALID-T Batch 2)
// =============================================================================
/** Both mcp/snapshot-created and mcp/file-modified return this acknowledgement */
export const MCPAcknowledgedResult = z.object({
    acknowledged: z.literal(true),
});
/**
 * File modified notification parameters
 */
export const MCPFileModifiedParams = WorkspaceBase.extend({
    /** File path */
    path: z.string().min(1),
    /** Lines changed */
    linesChanged: z.number().int().nonnegative().optional(),
    /** AI-attributed change */
    aiAttributed: z.boolean().optional(),
    /** AI tool that made the change */
    aiTool: z.enum(["cursor", "copilot", "claude", "windsurf", "burst-pattern"]).optional(),
});
