// ESM imports fixed for Node.js v22+
/**
 * Entity Schemas
 *
 * Core entity definitions for the local-service protocol.
 *
 * @module @vreko/contracts/local-service/schemas/entities
 */
import { z } from "zod";
import { CoChangeRelationship, ProtectionLevel, RiskLevel, SessionState, SnapshotTrigger, WarningSeverity, } from "./primitives.js";
// =============================================================================
// Core Entities
// =============================================================================
/**
 * File conflict between concurrent sessions
 *
 * Tracks overlapping file modifications between two sessions
 * running on the same workspace.
 */
export const FileConflict = z.object({
    /** The OTHER session ID involved in the conflict */
    sessionId: z.string(),
    /** Client type of the other session */
    clientType: z.enum(["vscode", "mcp-stdio", "mcp-remote", "cli", "api", "unknown"]),
    /** Overlapping file paths */
    files: z.array(z.string()),
    /** When the conflict was detected */
    detectedAt: z.number(),
    /** Severity level */
    severity: z.enum(["info", "warn"]),
});
/**
 * Session entity
 *
 * Represents a work session in the editor. Sessions group related snapshots
 * and track workspace activity.
 *
 * Phase 1 additions: clientId, clientType, endedAt, snapshotIds, learningIds,
 * coherenceScore, riskPeakScore, concurrentSessionIds, fileConflicts, touchedFiles.
 */
export const Session = z.object({
    /** Unique session identifier (UUID v4) */
    id: z.string().uuid(),
    /** Absolute path to the workspace root */
    workspacePath: z.string(),
    /** ISO 8601 timestamp when session started */
    startedAt: z.string().datetime(),
    /** ISO 8601 timestamp of last activity */
    lastActivityAt: z.string().datetime(),
    /** Current session state */
    state: SessionState,
    /** Session metadata */
    metadata: z.object({
        /** AI tools detected during this session */
        aiToolsDetected: z.array(z.string()),
        /** Highest risk level seen in this session */
        highestRiskLevel: RiskLevel,
        /** Count of snapshots by trigger type */
        triggerCounts: z.record(z.string(), z.number()),
    }),
    // === Phase 1 Additions ===
    /** Client ID that owns this session (populated from ClientRegistry) */
    clientId: z.string().optional(),
    /** Client type (vscode, mcp-stdio, mcp-remote, cli, api, unknown) */
    clientType: z.enum(["vscode", "mcp-stdio", "mcp-remote", "cli", "api", "unknown"]).optional(),
    /** Unix ms timestamp when session ended (null if active) */
    endedAt: z.number().nullable().optional(),
    /** Snapshot IDs created during this session */
    snapshotIds: z.array(z.string()).optional(),
    /** Learning IDs captured during this session */
    learningIds: z.array(z.string()).optional(),
    /** Coherence score computed at session end */
    coherenceScore: z.enum(["high", "medium", "low", "scattered"]).nullable().optional(),
    /** Maximum risk score observed during session */
    riskPeakScore: z.number().nullable().optional(),
    /** Other active sessions on same workspace */
    concurrentSessionIds: z.array(z.string()).optional(),
    /** Cross-session file overlap detections */
    fileConflicts: z.array(FileConflict).optional(),
    /** Files touched during this session */
    touchedFiles: z.array(z.string()).optional(),
});
/**
 * Snapshot entity
 *
 * Represents a point-in-time capture of a file's state. Snapshots are the
 * core unit of protection in Vreko.
 */
export const Snapshot = z.object({
    /** Unique snapshot identifier (UUID v4) */
    id: z.string().uuid(),
    /** Session that created this snapshot */
    sessionId: z.string().min(1),
    /** Absolute path to the file */
    filePath: z.string(),
    /** Path relative to workspace root */
    relativePath: z.string(),
    /** Content hash (SHA-256, prefixed with "sha256:") */
    contentHash: z.string().startsWith("sha256:"),
    /** What triggered this snapshot */
    trigger: SnapshotTrigger,
    /** ISO 8601 timestamp when snapshot was created */
    createdAt: z.string().datetime(),
    /** Snapshot metadata */
    metadata: z.object({
        /** File size in bytes */
        fileSize: z.number().int().nonnegative(),
        /** Number of lines in the file */
        lineCount: z.number().int().nonnegative(),
        /** Programming language (optional) */
        language: z.string().optional(),
        /** AI tool that was active (if detected) */
        aiToolDetected: z.string().optional(),
        /** Confidence score for AI detection (0-1) */
        aiConfidence: z.number().min(0).max(1).optional(),
        /** Risk level assessment (optional) */
        riskLevel: RiskLevel.optional(),
    }),
});
/**
 * Protection decision
 *
 * Result of evaluating protection policy for a file.
 */
export const ProtectionDecision = z.object({
    /** Determined protection level */
    level: ProtectionLevel,
    /** Whether this was automatically determined */
    automatic: z.boolean(),
    /** Source of the decision */
    source: z.enum(["auto", "user", "config", "default"]),
    /** Confidence in the decision (0-1) */
    confidence: z.number().min(0).max(1),
});
/**
 * Protection factor
 *
 * Individual factor contributing to a protection decision.
 */
export const ProtectionFactor = z.object({
    /** Factor name/description */
    name: z.string(),
    /** Factor score (0-1, higher = more protection needed) */
    score: z.number().min(0).max(1),
    /** Factor weight in overall decision (0-1) */
    weight: z.number().min(0).max(1),
    /** Additional details (optional) */
    details: z.string().optional(),
});
/**
 * Detection signal
 *
 * Evidence of AI tool activity.
 */
export const DetectionSignal = z.object({
    /** Type of detection signal */
    type: z.enum(["pattern", "timing", "volume", "style"]),
    /** Human-readable description */
    description: z.string(),
    /** Signal strength (0-1, higher = stronger evidence) */
    strength: z.number().min(0).max(1),
});
/**
 * Risk factor
 *
 * Individual risk identified in code changes.
 */
export const RiskFactor = z.object({
    /** Risk category */
    category: z.enum(["security", "stability", "data", "infrastructure"]),
    /** Human-readable description */
    description: z.string(),
    /** Severity level */
    severity: z.enum(["low", "medium", "high"]),
    /** Location in code (optional) */
    location: z
        .object({
        /** Starting line number (1-indexed) */
        startLine: z.number().int().positive(),
        /** Ending line number (1-indexed) */
        endLine: z.number().int().positive(),
    })
        .optional(),
});
// =============================================================================
// Intelligence Insights Response Entities
// =============================================================================
/**
 * Risk assessment result returned by protection/evaluate
 *
 * Maps directly from RiskAssessment in packages/intelligence/src/types/integrations.ts
 * Serialized for IPC transport (no class instances, no functions).
 */
export const RiskAssessmentResponse = z.object({
    /** Overall risk score: 0-100 */
    score: z.number().int().min(0).max(100),
    /** Risk level classification (reuses existing RiskLevel from local-service) */
    level: RiskLevel,
    /** All identified risk factors */
    factors: z.array(z.object({
        /** Factor name */
        name: z.string(),
        /** Score contribution: -100 to 100 */
        score: z.number().min(-100).max(100),
        /** Human-readable description */
        description: z.string(),
        /** Source system */
        source: z.enum(["github", "context7", "sentry", "local", "ai_detection"]),
        /** Optional mitigation suggestion */
        suggestion: z.string().optional(),
    })),
    /** Recommended action */
    recommendation: z.enum(["proceed", "warn", "block"]),
    /** Confidence in assessment: 0-100 */
    confidence: z.number().int().min(0).max(100),
    /** Human-readable explanation */
    explanation: z.string(),
});
/**
 * AI detection result returned by detection/check
 *
 * v2 FIX (M6): Uses discriminated union instead of nullable toolName.
 * `detected: false` = checked and clean. `detected: true` = AI tool found.
 * Eliminates ambiguity between "not checked" and "checked, not found".
 */
export const AIDetectionResult = z.discriminatedUnion("detected", [
    z.object({
        detected: z.literal(false),
        /** Detection confidence: 0-1 (confidence that no AI was involved) */
        confidence: z.number().min(0).max(1),
        /** Detection signals evaluated */
        signals: z.array(z.object({
            type: z.enum(["pattern", "timing", "volume", "style"]),
            description: z.string(),
            strength: z.number().min(0).max(1),
        })),
    }),
    z.object({
        detected: z.literal(true),
        /** Detected AI tool name */
        toolName: z.string(),
        /** Detection confidence: 0-1 */
        confidence: z.number().min(0).max(1),
        /** Detection signals that contributed to the result */
        signals: z.array(z.object({
            type: z.enum(["pattern", "timing", "volume", "style"]),
            description: z.string(),
            strength: z.number().min(0).max(1),
        })),
    }),
]);
/**
 * Fragile file entry
 *
 * A file identified as having high rollback risk based on historical patterns.
 */
export const FragileFile = z.object({
    /** Relative file path */
    filePath: z.string(),
    /** Fragility score: 0-1 (1 = very fragile) */
    fragilityScore: z.number().min(0).max(1),
    /** Severity classification */
    severity: z.enum(["moderate", "high", "critical"]),
    /** Why this file is fragile */
    reason: z.string(),
    /** Suggested action */
    suggestion: z.string(),
    /** Number of rollbacks in recent history */
    rollbackCount: z.number().int().nonnegative(),
    /** Number of AI-triggered modifications */
    aiChurnCount: z.number().int().nonnegative(),
    /** Blast radius (number of dependent files) */
    blastRadius: z.number().int().nonnegative().optional(),
    /** Last modified timestamp (ISO 8601) */
    lastModified: z.string().datetime().optional(),
});
/**
 * Co-change pattern entry
 *
 * Two files that are frequently modified together, indicating a dependency
 * relationship that the developer should be aware of.
 */
export const CoChangePattern = z.object({
    /** Primary file path */
    fileA: z.string(),
    /** Co-changed file path */
    fileB: z.string(),
    /** Co-occurrence frequency: 0-1 (1 = always changed together) */
    frequency: z.number().min(0).max(1),
    /** Number of times these files were changed together */
    occurrences: z.number().int().positive(),
    /** Relationship type  -  extensible union */
    relationship: CoChangeRelationship,
    /** Human-readable description of why they co-change */
    reason: z.string(),
    /** When this pattern was last observed (ISO 8601) */
    lastObserved: z.string().datetime(),
});
// =============================================================================
// STORAGE SCHEMAS (Phase 1 - Service Layer Contracts)
// =============================================================================
/**
 * FragileFileStorageSchema - validates what baseline.ts actually returns
 *
 * This is the Phase 1 service contract for the BaselineService.
 * Uses 0-100 scale for compositeScore (not 0-1 like the API schema).
 */
export const FragileFileStorageSchema = z.object({
    /** Relative file path */
    path: z.string().min(1),
    /** Composite fragility score: 0-100 (100 = most fragile) */
    compositeScore: z.number().min(0).max(100),
    /** Weighted churn rate contribution */
    churnScore: z.number().min(0),
    /** Weighted dependency count contribution */
    blastRadiusScore: z.number().min(0),
    /** How often restores involve this file */
    rollbackScore: z.number().min(0),
    /** Files that import this file */
    dependentCount: z.number().int().nonnegative(),
    /** Ranking: 1 = most fragile */
    rank: z.number().int().positive(),
});
/**
 * CoChangePatternStorageSchema - validates what CoChangeDetector.ts actually returns
 *
 * This is the Phase 1 service contract for the CoChangeDetector.
 * Uses epoch number for lastObserved (not ISO string like the API schema).
 */
export const CoChangePatternStorageSchema = z.object({
    /** Primary file path */
    fileA: z.string().min(1),
    /** Co-changed file path */
    fileB: z.string().min(1),
    /** Co-occurrence frequency: 0-1 (1 = always changed together) */
    frequency: z.number().min(0).max(1),
    /** Number of times these files were changed together */
    occurrences: z.number().int().positive(),
    /** Relationship type  -  extensible string */
    relationship: z.string().min(1),
    /** Human-readable description of why they co-change */
    reason: z.string().min(1),
    /** When this pattern was last observed (epoch timestamp) */
    lastObserved: z.number().int().positive(),
});
/**
 * RiskFactorStorageSchema - validates the RiskFactor shape returned by the risk assessment service
 */
export const RiskFactorStorageSchema = z.object({
    /** Pillar source */
    source: z.enum([
        "git-risk",
        "rollback-patterns",
        "fatigue",
        "annotations",
        "poisoning",
        "history",
        "structural",
        "co-change",
    ]),
    /** Risk score contribution */
    score: z.number(),
    /** Human-readable description */
    description: z.string().min(1),
    /** Severity level */
    severity: z.enum(["info", "warning", "critical"]),
    /** Additional metadata */
    meta: z.record(z.unknown()).optional(),
});
/**
 * RiskAssessmentStorageSchema - validates what the risk assessment service actually returns
 *
 * This is the Phase 2 service contract for the risk assessment service.
 * Uses epoch number for timestamp (not ISO string).
 */
export const RiskAssessmentStorageSchema = z.object({
    /** Overall risk score (1.0 = neutral, higher = riskier) */
    riskScore: z.number().min(0),
    /** Action recommendation */
    action: z.enum(["PROCEED", "PROCEED_WITH_SNAPSHOT", "WARN", "BLOCK"]),
    /** All contributing factors */
    factors: z.array(RiskFactorStorageSchema),
    /** Whether write is allowed */
    allowed: z.boolean(),
    /** Human-readable recommendation */
    recommendation: z.string().min(1),
    /** Alternative actions if blocked */
    alternativeActions: z
        .array(z.object({
        tool: z.string(),
        description: z.string(),
        params: z.record(z.unknown()).optional(),
    }))
        .optional(),
    /** Assessment timestamp (epoch) */
    timestamp: z.number().int().positive(),
    /** Correlation ID for tracing */
    correlationId: z.string().optional(),
});
/**
 * Workspace intelligence summary
 *
 * Aggregated intelligence state for a workspace  -  the "headline" data
 * that tells users what Vreko knows about their codebase.
 *
 * v2 FIX (Finding 10): Added time-windowed counters alongside cumulative totals.
 * Cumulative totals retained for Pioneer Program / gamification; windowed counters
 * provide meaningful recency signals in the UI.
 */
export const WorkspaceIntelligenceSummary = z.object({
    /** Total learnings captured for this workspace */
    learningsCount: z.number().int().nonnegative(),
    /** Total patterns detected */
    patternsCount: z.number().int().nonnegative(),
    /** Number of fragile files identified */
    fragileFilesCount: z.number().int().nonnegative(),
    /** Number of co-change relationships detected */
    coChangePatternsCount: z.number().int().nonnegative(),
    /** Total sessions recorded (cumulative) */
    totalSessions: z.number().int().nonnegative(),
    /** Total lines analyzed (cumulative  -  retained for Pioneer Program) */
    linesAnalyzed: z.number().int().nonnegative(),
    /** Total snapshots created (cumulative) */
    totalSnapshots: z.number().int().nonnegative(),
    /** Total restores performed (cumulative) */
    totalRestores: z.number().int().nonnegative(),
    // ── Time-windowed counters (v2  -  meaningful recency) ──
    /** Snapshots created in the last 24 hours */
    snapshotsToday: z.number().int().nonnegative(),
    /** Snapshots created in the last 7 days */
    snapshotsThisWeek: z.number().int().nonnegative(),
    /** Lines analyzed in the last 24 hours */
    linesAnalyzedToday: z.number().int().nonnegative(),
    /** Restores performed in the last 7 days */
    restoresThisWeek: z.number().int().nonnegative(),
    /** Patterns detected in the last 7 days */
    patternsThisWeek: z.number().int().nonnegative(),
    // ── Health summary ──
    /** Workspace health score: 0-100 */
    healthScore: z.number().int().min(0).max(100),
    /** Health trajectory */
    healthTrajectory: z.enum(["improving", "stable", "declining"]),
});
/**
 * Active warning from the advisory engine
 */
export const ActiveWarning = z.object({
    /** Warning code (e.g., 'FRAGILE_FILE', 'LOOP_DETECTED') */
    code: z.string(),
    /** Severity level (ordered: info < warning < error) */
    level: WarningSeverity,
    /** Human-readable message */
    message: z.string(),
    /** Affected file (optional) */
    file: z.string().optional(),
    /** Suggested action */
    suggestion: z.string().optional(),
});
/**
 * Session coherence assessment
 */
export const SessionCoherence = z.object({
    /** Coherence score: 0-100 (100 = highly focused session) */
    score: z.number().int().min(0).max(100),
    /** Assessment */
    assessment: z.enum(["focused", "moderate", "scattered", "chaotic"]),
    /** Number of distinct file clusters in the session */
    clusterCount: z.number().int().nonnegative(),
    /** Primary focus area (most-edited directory or module) */
    primaryFocus: z.string().nullable(),
    /** Files that seem unrelated to the main session focus */
    outlierFiles: z.array(z.string()),
});
/**
 * AI attribution for a snapshot.
 *
 * v2 FIX (M6): Discriminated union eliminates null ambiguity.
 * `detected: false` = AI check ran, nothing found.
 * `detected: true` = AI tool was identified.
 * Field is optional on EnrichedSnapshot  -  absent = not yet checked.
 */
export const SnapshotAIAttribution = z.discriminatedUnion("detected", [
    z.object({ detected: z.literal(false) }),
    z.object({
        detected: z.literal(true),
        toolName: z.string(),
        confidence: z.number().min(0).max(1),
    }),
]);
/**
 * Enriched snapshot for timeline display
 *
 * Standard Snapshot entity + intelligence annotations.
 * This is what the webview renders in the Activity timeline.
 */
export const EnrichedSnapshot = Snapshot.extend({
    /** Risk assessment at time of creation */
    risk: z
        .object({
        score: z.number().int().min(0).max(100),
        level: RiskLevel,
    })
        .optional(),
    /** AI tool attribution (absent = not checked, present = checked) */
    aiAttribution: SnapshotAIAttribution.optional(),
    /** Session cluster ID (for grouping in timeline) */
    sessionClusterId: z.string().uuid().nullable(),
    /** Whether this snapshot has been restored */
    wasRestored: z.boolean(),
});
// =============================================================================
// DataSection<T>  -  v4 Addition for Webview State Management
// =============================================================================
/**
 * Status envelope for data sections with loading/error/stale states.
 * Enables per-section graceful degradation in webview.
 *
 * v4 FIX (C1.3): DataSection<T> not in contracts  -  now added.
 *
 * @example
 * ```typescript
 * const section: DataSection<FragileFile[]> = {
 *   status: "ready",
 *   data: [{ filePath: "auth.ts", fragilityScore: 0.8 }],
 *   fetchedAt: Date.now()
 * };
 * ```
 */
export const DataSectionSchema = (dataSchema) => z.discriminatedUnion("status", [
    z.object({ status: z.literal("loading") }),
    z.object({
        status: z.literal("ready"),
        data: dataSchema,
        fetchedAt: z.number(),
    }),
    z.object({
        status: z.literal("error"),
        error: z.string(),
        staleData: dataSchema.optional(),
        fetchedAt: z.number().optional(),
    }),
    z.object({
        status: z.literal("stale"),
        data: dataSchema,
        fetchedAt: z.number(),
    }),
]);
// =============================================================================
// Topology  -  blast radius RPC (Project Bedrock Phase 1)
// =============================================================================
/**
 * Params for `topology/blast-radius`.
 *
 * Canonical principle (spec §1.3): every topology query carries the
 * workspace path so the daemon can route to the correct per-workspace
 * TopologyService singleton.
 */
export const topologyBlastRadiusParams = z.object({
    /** Workspace root (absolute path) */
    workspace: z.string().min(1),
    /** Workspace-relative file path (I-9) */
    filePath: z.string().min(1),
});
/**
 * Result shape of `topology/blast-radius`.
 *
 * When the TopologyService has not yet populated its scan cache, the
 * `result` field is `null`  -  callers should fall back to baseline data
 * rather than treating this as an error (spec §3 Phase 1 Step 1.5).
 */
export const topologyBlastRadiusResult = z.object({
    result: z
        .object({
        /** 1-hop importers (workspace-relative paths) */
        direct: z.array(z.string()),
        /** 2-hop importers, excluding anything in `direct` */
        transitive: z.array(z.string()),
        directCount: z.number().int().nonnegative(),
        transitiveCount: z.number().int().nonnegative(),
        /** Count of affected files living in a different module */
        crossPackageCount: z.number().int().nonnegative(),
        /** Log-scale normalised blast radius score in [0, 1] */
        score: z.number().min(0).max(1),
    })
        .nullable(),
});
