// ESM imports fixed for Node.js v22+
/**
 * Intelligence Pillars - Schemas for 6 Intelligence Pillars
 *
 * Phase 1: Production Implementation of Detection Enhancement
 * - Pillar 01: Git State as Risk Multiplier
 * - Pillar 02: Rollback Clustering (The Moat)
 * - Pillar 03: Copilot Fatigue Detection
 * - Pillar 04: Zero-Friction Checkpoint Annotations
 * - Pillar 05: Context Poisoning Detection
 * - Pillar 06: Pre-Write MCP Interception (composite)
 *
 * @module @vreko/contracts/local-service/schemas/intelligence-pillars
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
// =============================================================================
// Pillar 01: Git State as Risk Multiplier
// =============================================================================
/**
 * Git Risk Factor - individual contributing factor to git risk score
 */
export const GitRiskFactor = z.object({
    /** Unique identifier for this risk factor */
    id: z.string(),
    /** Human-readable label */
    label: z.string(),
    /** Contribution to risk multiplier (additive) */
    contribution: z.number(),
    /** Severity level */
    severity: z.enum(["info", "warning", "critical"]),
});
/**
 * Git Risk Score - result of git state evaluation
 *
 * The multiplier is applied to base risk scores to amplify risk
 * when working in dangerous git states (e.g., on main branch, during rebase)
 */
export const GitRiskScore = z.object({
    /** Multiplicative factor applied to base risk score (1.0 = neutral) */
    multiplier: z.number(),
    /** Contributing factors that built up the multiplier */
    factors: z.array(GitRiskFactor),
    /** Whether git context was available */
    hasGitContext: z.boolean(),
    /** Timestamp of evaluation for caching */
    evaluatedAt: z.number(),
});
/**
 * Git Risk Context Params - parameters for risk/git-context method
 */
export const GitRiskContextParams = z.object({
    /** Workspace path to evaluate */
    workspace: z.string(),
});
// =============================================================================
// Pillar 02: Rollback Clustering (The Moat)
// =============================================================================
/**
 * Rollback Event - single rollback occurrence for pattern learning
 */
export const RollbackEvent = z.object({
    /** AI tool that was active when rollback happened */
    tool: z.string(),
    /** File extension involved */
    fileExt: z.string(),
    /** Number of lines in the rolled-back change */
    linesChanged: z.number(),
    /** Programming language */
    language: z.string(),
    /** File category classification */
    fileCategory: z.enum(["config", "code", "test", "docs", "build", "other"]),
    /** Was it a multi-file change? */
    fileCount: z.number(),
    /** Time of day bucket (0-23) for fatigue correlation */
    hourBucket: z.number().int().min(0).max(23),
    /** Session duration at rollback time (minutes) */
    sessionMinutes: z.number(),
    /** Workspace where rollback occurred */
    workspace: z.string(),
    /** Timestamp of rollback */
    timestamp: z.number(),
});
/**
 * Rollback Warning - warning that a proposed change matches a known failure pattern
 */
export const RollbackWarning = z.object({
    /** Confidence that this matches a known failure pattern (0-1) */
    confidence: z.number().min(0).max(1),
    /** Human-readable warning message */
    message: z.string(),
    /** Number of similar rollbacks in the cluster */
    clusterSize: z.number(),
    /** Dominant factors in the cluster */
    dominantFactors: z.array(z.string()),
    /** Risk boost to apply (additive) */
    riskBoost: z.number(),
});
/**
 * Record Rollback Params - parameters for risk/rollback-record method
 */
export const RollbackRecordParams = z.object({
    /** Workspace where rollback occurred */
    workspace: z.string(),
    /** AI tool that was active */
    tool: z.string(),
    /** File extension */
    fileExt: z.string(),
    /** Lines changed */
    linesChanged: z.number(),
    /** Programming language */
    language: z.string(),
    /** File category */
    fileCategory: z.enum(["config", "code", "test", "docs", "build", "other"]),
    /** File count */
    fileCount: z.number(),
    /** Session duration in minutes */
    sessionMinutes: z.number(),
});
/**
 * Rollback Warning Params - parameters for risk/rollback-warning method
 */
export const RollbackWarningParams = z.object({
    /** Workspace to check */
    workspace: z.string(),
    /** AI tool making the change */
    tool: z.string(),
    /** File extension */
    fileExt: z.string(),
    /** Lines being changed */
    linesChanged: z.number(),
    /** Programming language */
    language: z.string(),
    /** File category */
    fileCategory: z.enum(["config", "code", "test", "docs", "build", "other"]),
    /** File count in change */
    fileCount: z.number(),
    /** Current session duration */
    sessionMinutes: z.number(),
});
/**
 * Rollback Stats Params - parameters for risk/rollback-stats method
 */
export const RollbackStatsParams = z.object({
    /** Workspace to get stats for */
    workspace: z.string(),
});
/**
 * Rollback Stats - statistics about rollback patterns in a workspace
 */
export const RollbackStats = z.object({
    /** Total rollbacks recorded */
    totalRollbacks: z.number(),
    /** Number of distinct clusters */
    clusters: z.number(),
    /** Size of largest cluster */
    largestCluster: z.number(),
});
// =============================================================================
// Pillar 03: Copilot Fatigue Detection
// =============================================================================
/**
 * Fatigue Assessment - result of fatigue detection analysis
 *
 * Detects "rubber-stamping" when developers accept AI suggestions
 * faster than they could read them.
 */
export const FatigueAssessment = z.object({
    /** Additive risk boost (0.0 - 0.5) */
    riskBoost: z.number().min(0).max(0.5),
    /** Human-readable fatigue level */
    level: z.enum(["rested", "normal", "elevated", "fatigued"]),
    /** Ratio of rapid accepts in the window (0-1) */
    rapidAcceptRatio: z.number().min(0).max(1),
    /** Current accept velocity (accepts per minute) */
    velocityPerMinute: z.number(),
    /** Session duration contributing to assessment */
    sessionMinutes: z.number(),
    /** Contributing factors to the assessment */
    factors: z.array(z.string()),
});
/**
 * Fatigue Params - parameters for risk/fatigue method
 */
export const FatigueParams = z.object({
    /** Workspace to assess */
    workspace: z.string(),
});
// =============================================================================
// Pillar 04: Zero-Friction Checkpoint Annotations
// =============================================================================
/**
 * Annotation Tag - classification of checkpoint state
 */
export const AnnotationTag = z.enum([
    "good_state", // Developer affirms: this code was correct
    "before_refactor", // About to make structural changes
    "it_broke_here", // Marks the point of failure
    "uncertain", // Developer unsure  -  higher protection warranted
    "ai_diverged", // AI went in wrong direction
    "manual_recovery", // Developer manually fixed something
    "shipped", // This state was deployed
]);
/**
 * Checkpoint Annotation - annotation of a snapshot state
 */
export const CheckpointAnnotation = z.object({
    /** Snapshot hash (content-addressable ID) */
    snapshotHash: z.string(),
    /** Annotation tag */
    tag: AnnotationTag,
    /** Optional freeform note (max 280 chars) */
    note: z.string().max(280).optional(),
    /** Active AI tool at time of annotation */
    aiTool: z.string().optional(),
    /** Files in the snapshot */
    fileCount: z.number(),
    /** Risk score at time of annotation */
    riskScore: z.number().optional(),
    /** Timestamp */
    timestamp: z.number(),
    /** Workspace */
    workspace: z.string(),
});
/**
 * Annotate Params - parameters for intelligence/annotate method
 */
export const IntelligenceAnnotateParams = z.object({
    /** Snapshot hash to annotate */
    snapshotHash: z.string(),
    /** Annotation tag */
    tag: AnnotationTag,
    /** Optional note */
    note: z.string().max(280).optional(),
    /** AI tool active */
    aiTool: z.string().optional(),
    /** File count */
    fileCount: z.number(),
    /** Risk score at time */
    riskScore: z.number().optional(),
    /** Workspace */
    workspace: z.string(),
});
/**
 * Annotate Result - result of annotation operation
 */
export const AnnotateResult = z.object({
    /** Whether annotation was recorded */
    recorded: z.boolean(),
    /** Risk signal from the annotation */
    riskSignal: z.object({
        direction: z.enum(["increase", "decrease", "neutral"]),
        magnitude: z.number(),
    }),
});
/**
 * Query Annotations Params - parameters for intelligence/annotations-query method
 */
export const QueryAnnotationsParams = z.object({
    /** Workspace to query */
    workspace: z.string(),
    /** Filter by timestamp (ms since epoch) */
    since: z.number().optional(),
    /** Filter by tags */
    tags: z.array(AnnotationTag).optional(),
    /** Limit number of results */
    limit: z.number().optional(),
});
/**
 * Risk Calibration Params - parameters for intelligence/risk-calibration method
 */
export const RiskCalibrationParams = z.object({
    /** Workspace to get calibration for */
    workspace: z.string(),
});
/**
 * Risk Calibration - net risk adjustment from annotations
 */
export const RiskCalibration = z.object({
    /** Net risk adjustment from historical annotations */
    netAdjustment: z.number().min(-0.5).max(0.5),
    /** Number of annotations considered */
    annotationCount: z.number(),
    /** Breakdown by tag */
    breakdown: z.record(AnnotationTag, z.number()),
});
// =============================================================================
// Pillar 05: Context Poisoning Detection
// =============================================================================
/**
 * Poisoning Check Result - result of checking for context poisoning
 *
 * Detects when AI repeatedly generates the same incorrect pattern,
 * indicating stale or corrupted context model.
 */
export const PoisoningCheckResult = z.object({
    /** Whether poisoning was detected */
    isPoisoned: z.boolean(),
    /** How many times this pattern has been rejected */
    occurrences: z.number(),
    /** How many distinct sessions it appeared in */
    distinctSessions: z.number(),
    /** Risk boost to apply if poisoned */
    riskBoost: z.number(),
    /** Human-readable warning */
    warning: z.string().optional(),
    /** Structural fingerprint (for debugging) */
    fingerprint: z.string().optional(),
});
/**
 * Poisoning Check Params - parameters for risk/poisoning-check method
 */
export const PoisoningCheckParams = z.object({
    /** Workspace to check */
    workspace: z.string(),
    /** Unified diff of proposed change */
    diff: z.string(),
});
/**
 * Poisoning Log Rejection Params - parameters for risk/poisoning-log-rejection method
 */
export const PoisoningLogRejectionParams = z.object({
    /** Workspace where rejection occurred */
    workspace: z.string(),
    /** Diff that was rejected */
    diff: z.string(),
    /** Session ID */
    sessionId: z.string(),
    /** AI tool involved */
    tool: z.string().optional(),
    /** File extension */
    fileExt: z.string().optional(),
});
/**
 * Poisoning Stats Params - parameters for risk/poisoning-stats method
 */
export const PoisoningStatsParams = z.object({
    /** Workspace to get stats for */
    workspace: z.string(),
});
/**
 * Poisoning Stats - statistics about poisoning detection
 */
export const PoisoningStats = z.object({
    /** Number of patterns being tracked */
    trackedPatterns: z.number(),
    /** Number of poisoned patterns (>= threshold) */
    poisonedPatterns: z.number(),
    /** Top tools involved in poisoning */
    topTools: z.array(z.string()),
});
// =============================================================================
// Pillar 06: Pre-Write MCP Interception (Composite)
// =============================================================================
/**
 * Safe To Write Action - decision from pre-write evaluation
 */
export const SafeToWriteAction = z.enum([
    "PROCEED", // Safe  -  auto-snapshot and write
    "PROCEED_WITH_SNAPSHOT", // Elevated risk  -  explicit snapshot first
    "WARN", // High risk  -  surface warning to user
    "BLOCK", // Critical risk  -  require manual review
]);
/**
 * Safe To Write Factor - individual risk factor contributing to decision
 */
export const SafeToWriteFactor = z.object({
    /** Source of the factor (which pillar) */
    source: z.string(),
    /** Score contribution */
    score: z.number(),
    /** Description of the factor */
    description: z.string(),
});
/**
 * Alternative Action - suggested alternative when write is blocked
 */
export const AlternativeAction = z.object({
    /** Tool to use instead */
    tool: z.string(),
    /** Description of what to do */
    description: z.string(),
    /** Optional parameters for the tool */
    params: z.record(z.string(), z.unknown()).optional(),
});
/**
 * Safe To Write Result - result of pre-write safety check
 *
 * This is the composite result from all 5 intelligence pillars,
 * used by MCP tools before writing files.
 */
export const SafeToWriteResult = z.object({
    /** Whether the write is allowed */
    allowed: z.boolean(),
    /** Action to take */
    action: SafeToWriteAction,
    /** Composite risk score (capped at 2.5) */
    riskScore: z.number(),
    /** Contributing factors from all pillars */
    factors: z.array(SafeToWriteFactor),
    /** Human-readable recommendation */
    recommendation: z.string(),
    /** Snapshot hash if auto-created */
    snapshotHash: z.string().optional(),
    /** Whether the operation can be retried */
    retryable: z.boolean(),
    /** Alternative actions to take instead */
    alternativeActions: z.array(AlternativeAction),
});
/**
 * Safe To Write Params - parameters for protection/safe-to-write method
 * (used by MCP tools)
 */
export const SafeToWriteParams = z.object({
    /** Workspace path */
    workspace: z.string(),
    /** File path being written */
    filePath: z.string(),
    /** Proposed diff */
    proposedDiff: z.string(),
    /** AI tool making the change */
    tool: z.string().optional(),
    /** Intent of the change */
    intent: z.string().optional(),
});
// =============================================================================
// Risk Assess (MCP → Daemon bridge  -  accepts both MCP and daemon param shapes)
// =============================================================================
/**
 * Risk Assess Params - parameters for risk/assess method
 *
 * The MCP tool sends { workspace, files, context: { task, sessionId } }
 * but the daemon routing destructures { workspace, filePath, proposedDiff, tool, intent, sessionId }.
 * This schema accepts BOTH shapes; the daemon routing code handles the union.
 */
export const RiskAssessParams = WorkspaceBase.extend({
    /** Single file path (daemon shape) */
    filePath: z.string().optional(),
    /** Array of file paths (MCP shape) */
    files: z.array(z.string()).optional(),
    /** Proposed diff content */
    proposedDiff: z.string().optional(),
    /** AI tool making the request */
    tool: z.string().optional(),
    /** Intent of the change */
    intent: z.string().optional(),
    /** Session ID (daemon shape - top-level) */
    sessionId: z.string().optional(),
    /** Context object (MCP shape - nested) */
    context: z
        .object({
        task: z.string().optional(),
        sessionId: z.string().optional(),
    })
        .optional(),
});
