// ESM imports fixed for Node.js v22+
/**
 * Guard Health Schemas
 *
 * Zod schemas for the guard health intelligence system (SB-HEALTH-001).
 * Matches the NDJSON output contract from scripts/guards/*.sh
 *
 * @module @vreko/contracts/local-service/schemas/guard
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
// =============================================================================
// Guard Status Enum
// =============================================================================
/**
 * Guard execution status
 *
 * Matches the exit codes from guard shell scripts:
 * - pass: Guard completed successfully, no issues found (exit 0)
 * - warn: Guard found issues but they are not blocking (exit 0 with warnings)
 * - fail: Guard found critical issues or execution failed (exit 1)
 */
export const GuardStatus = z.enum(["pass", "warn", "fail"]);
// =============================================================================
// Guard File
// =============================================================================
/**
 * A file flagged by a guard with optional line number and message
 *
 * Corresponds to individual violation records from guard output.
 */
export const GuardFile = z.object({
    /** Absolute or workspace-relative path to the flagged file */
    path: z.string().min(1),
    /** Line number where the issue was found (optional) */
    line: z.number().int().positive().optional(),
    /** Human-readable description of the issue */
    message: z.string().min(1),
});
// =============================================================================
// Guard Result
// =============================================================================
/**
 * Result from a single guard execution
 *
 * Matches the NDJSON line format from `run-guards.sh --format json`.
 * Each line of stdout represents one guard's results.
 */
export const GuardResult = z.object({
    /** Guard name (e.g., "console-logs", "test-pollution") */
    guard: z.string().min(1),
    /** Execution status */
    status: GuardStatus,
    /** Files flagged by this guard (empty array if status is "pass") */
    files: z.array(GuardFile).default([]),
    /** Execution duration in milliseconds */
    durationMs: z.number().nonnegative(),
});
// =============================================================================
// Guard Run Result
// =============================================================================
/**
 * Complete guard run result for a workspace
 *
 * Returned by the `health/workspace` IPC method.
 * Combines all guard results with metadata about cache staleness.
 */
export const GuardRunResult = z.object({
    /** Results from all guards in the run */
    guards: z.array(GuardResult).default([]),
    /** Unix timestamp (ms) when this run completed */
    timestamp: z.number().nonnegative(),
    /** Age of cached results in milliseconds (Date.now() - timestamp) */
    staleMs: z.number().nonnegative(),
    /** Profile used for this run ("fast" or "full") */
    profile: z.enum(["fast", "full"]),
    /** Whether a background refresh is in progress */
    refreshing: z.boolean(),
});
// =============================================================================
// IPC Method Params
// =============================================================================
/**
 * Parameters for health/workspace IPC method
 */
export const HealthWorkspaceParams = WorkspaceBase.extend({
    /** Guard profile to run (optional, defaults to "fast") */
    profile: z.enum(["fast", "full"]).optional().default("fast"),
});
// =============================================================================
// Notification Payload
// =============================================================================
/**
 * Payload for health.guard.changed notification
 *
 * Emitted when guard statuses change (e.g., pass→fail, warn→pass).
 * Only includes guards whose status actually changed.
 */
export const GuardChangedPayload = z.object({
    /** Guards that changed status since last run */
    changed: z.array(GuardResult),
    /** Current state of all guards */
    current: z.array(GuardResult),
    /** Unix timestamp (ms) when the change was detected */
    timestamp: z.number().nonnegative(),
});
