import { z } from "zod";
// =============================================================================
// LEARNING DATA MODEL (Phase 0 - Proactive Learning System)
// =============================================================================
/**
 * Learning types - categorical classification of captured learnings
 * - pattern: Reusable code/workflow patterns
 * - pitfall: Anti-patterns and bugs to avoid
 * - efficiency: Performance/optimization insights
 * - workflow: Process/tooling improvements
 * - discovery: New capabilities/features found
 */
export const LearningTypeSchema = z.enum([
    "pattern",
    "pitfall",
    "efficiency",
    "workflow",
    "discovery",
    "architecture",
    "performance",
]);
/**
 * Intent classification for command context matching
 */
export const LearningIntentSchema = z.enum(["implement", "debug", "refactor", "review"]);
/**
 * Action types - concrete, deterministic operations
 * Each learning maps to exactly one executable action
 */
export const LearningActionTypeSchema = z.enum(["add-flag", "set-env", "inject-validation", "warn", "suggest-file"]);
/**
 * Warning severity levels
 */
export const WarnSeveritySchema = z.enum(["info", "warning", "error"]);
// =============================================================================
// ACTION PAYLOAD SCHEMAS
// =============================================================================
/**
 * Payload for add-flag action
 * Adds CLI flag to command invocation
 */
export const AddFlagPayloadSchema = z.object({
    flag: z.string().min(1).describe("CLI flag to add, e.g. '--validate-expiry'"),
    value: z.union([z.string(), z.boolean()]).optional().describe("Flag value if applicable"),
    reason: z.string().min(1).describe("Human-readable reason shown in verbose mode"),
});
/**
 * Payload for set-env action
 * Sets environment variable for command execution
 */
export const SetEnvPayloadSchema = z.object({
    key: z
        .string()
        .min(1)
        .regex(/^[A-Z_][A-Z0-9_]*$/, "Must be valid env var name"),
    value: z.string().describe("Environment variable value"),
    reason: z.string().min(1).describe("Human-readable reason shown in verbose mode"),
});
/**
 * Payload for inject-validation action
 * Triggers validation logic during command execution
 */
export const InjectValidationPayloadSchema = z.object({
    validationType: z.string().min(1).describe("Validation type identifier, e.g. 'jwt-expiry', 'silent-catch'"),
    targetFile: z.string().optional().describe("Optional file to target for validation"),
    reason: z.string().min(1).describe("Human-readable reason shown in verbose mode"),
});
/**
 * Payload for warn action
 * Displays warning/info message to user
 */
export const WarnPayloadSchema = z.object({
    message: z.string().min(1).describe("Warning message to display"),
    severity: WarnSeveritySchema.describe("Severity level affects display styling"),
});
/**
 * Payload for suggest-file action
 * Suggests file creation based on established patterns
 */
export const SuggestFilePayloadSchema = z.object({
    filePath: z.string().min(1).describe("Suggested file path, may contain {feature} placeholder"),
    reason: z.string().min(1).describe("Human-readable reason for suggestion"),
});
// =============================================================================
// TRIGGER SCHEMA
// =============================================================================
/**
 * LearningTrigger - defines when a learning should be matched
 * All fields are optional; matching uses OR logic across populated fields
 */
export const LearningTriggerSchema = z.object({
    commands: z
        .array(z.string())
        .optional()
        .describe("Command names that trigger this learning, e.g. ['auth', 'deploy']"),
    intent: z.array(LearningIntentSchema).optional().describe("Intent types that trigger this learning"),
    filePatterns: z.array(z.string()).optional().describe("Glob patterns for file matching, e.g. ['**/*auth*.ts']"),
    flags: z.array(z.string()).optional().describe("CLI flags that trigger this learning, e.g. ['--provider']"),
    description: z.string().min(1).describe("Human-readable description for fuzzy matching"),
});
// =============================================================================
// ACTION SCHEMA (DISCRIMINATED UNION)
// =============================================================================
/**
 * LearningAction - concrete action to execute when learning is applied
 * Discriminated union ensures type-safe payload access
 */
export const LearningActionSchema = z.discriminatedUnion("type", [
    z.object({
        type: z.literal("add-flag"),
        payload: AddFlagPayloadSchema,
    }),
    z.object({
        type: z.literal("set-env"),
        payload: SetEnvPayloadSchema,
    }),
    z.object({
        type: z.literal("inject-validation"),
        payload: InjectValidationPayloadSchema,
    }),
    z.object({
        type: z.literal("warn"),
        payload: WarnPayloadSchema,
    }),
    z.object({
        type: z.literal("suggest-file"),
        payload: SuggestFilePayloadSchema,
    }),
]);
// =============================================================================
// MAIN LEARNING SCHEMA
// =============================================================================
/**
 * Learning - core data model for proactive learning system
 * Each learning represents a captured insight that can be applied to future commands
 */
export const LearningSchema = z.object({
    id: z.string().min(1).describe("Unique identifier for this learning"),
    type: LearningTypeSchema.describe("Categorical classification"),
    trigger: LearningTriggerSchema.describe("Conditions that activate this learning"),
    action: LearningActionSchema.describe("Concrete action to execute"),
    confidence: z.number().min(0).max(1).describe("Confidence score (0.0-1.0), static at creation"),
    created: z.number().int().positive().describe("Creation timestamp (ms since epoch)"),
    lastUsed: z.number().int().positive().optional().describe("Last usage timestamp (ms since epoch)"),
    usageCount: z.number().int().nonnegative().default(0).describe("Number of times this learning was applied"),
    tags: z.array(z.string()).default([]).describe("Searchable tags for categorization"),
    archived: z.boolean().default(false).describe("Whether this learning is archived (excluded from matching)"),
});
/**
 * Input type for creating new learnings
 * Omits auto-generated fields (id, created, lastUsed, usageCount)
 */
export const LearningInputSchema = LearningSchema.omit({
    id: true,
    created: true,
    lastUsed: true,
    usageCount: true,
    archived: true,
}).extend({
    tags: z.array(z.string()).optional().default([]),
    archived: z.boolean().optional(),
});
// =============================================================================
// LEARNING MODE & SESSION
// =============================================================================
/**
 * Learning evaluation modes - phased rollout support
 * - observe: Log matches only, no modification (Phase 1)
 * - warn: Apply warn-type actions only (Phase 2)
 * - apply-safe: Apply add-flag and warn only (Phase 3)
 * - apply-all: Apply all action types (opt-in)
 * - off: Skip evaluation entirely
 */
export const LearningModeSchema = z.enum(["observe", "warn", "apply-safe", "apply-all", "off"]);
/**
 * LearningSession - daemon-tracked session for repetition avoidance
 */
export const LearningSessionSchema = z.object({
    workspaceId: z.string().min(1),
    startedAt: z.number().int().positive(),
    lastCommandAt: z.number().int().positive(),
    appliedLearnings: z.array(z.string()).describe("Learning IDs applied in this session"),
});
// =============================================================================
// COMMAND TRIGGER SCOPE
// =============================================================================
/**
 * HIGH_VALUE_COMMANDS - commands that trigger learning evaluation by default
 */
export const HIGH_VALUE_COMMANDS = ["auth", "deploy", "verify", "migrate", "validate"];
/**
 * NEVER_EVALUATE_COMMANDS - commands that never trigger learning evaluation
 */
export const NEVER_EVALUATE_COMMANDS = ["help", "version", "status", "list"];
// =============================================================================
// EVALUATION TYPES
// =============================================================================
/**
 * Input for learning evaluation
 */
export const LearningEvaluationInputSchema = z.object({
    workspaceId: z.string().min(1),
    commandName: z.string().min(1),
    args: z.record(z.unknown()).optional().describe("Parsed command arguments/flags"),
    filesOrPaths: z.array(z.string()).optional().describe("Files involved in command"),
    intent: LearningIntentSchema.optional().describe("User intent if known"),
});
/**
 * Selected learning with score for evaluation result
 */
export const SelectedLearningSchema = z.object({
    id: z.string(),
    title: z.string().describe("Human-readable title derived from trigger.description"),
    type: LearningTypeSchema,
    score: z.number().min(0).max(1),
    action: LearningActionSchema,
    tags: z.array(z.string()),
});
/**
 * Result of learning evaluation
 */
export const LearningEvaluationResultSchema = z.object({
    selectedLearnings: z.array(SelectedLearningSchema),
    debug: z
        .object({
        evaluatedCount: z.number().int().nonnegative(),
        durationMs: z.number().nonnegative(),
        skippedReason: z.string().optional(),
    })
        .optional(),
});
// =============================================================================
// SENSITIVE DATA PATTERNS (for validation)
// =============================================================================
/**
 * Patterns that indicate sensitive data - learnings must not contain these
 */
export const SENSITIVE_DATA_PATTERNS = [
    /api[_-]?key/i,
    /secret/i,
    /password/i,
    /token/i,
    /credential/i,
    /private[_-]?key/i,
    /auth[_-]?token/i,
    /bearer/i,
    /ssh[_-]?key/i,
    /aws[_-]?access/i,
    /database[_-]?url/i,
    /connection[_-]?string/i,
];
/**
 * Check if a string contains sensitive data patterns
 */
export function containsSensitiveData(text) {
    return SENSITIVE_DATA_PATTERNS.some((pattern) => pattern.test(text));
}
// =============================================================================
// VALIDATION UTILITIES
// =============================================================================
/**
 * Validate a learning for sensitive data
 * Returns array of field paths containing sensitive data
 */
export function validateLearningForSensitiveData(learning) {
    const violations = [];
    // Check trigger description
    if (containsSensitiveData(learning.trigger.description)) {
        violations.push("trigger.description");
    }
    // Check trigger file patterns
    learning.trigger.filePatterns?.forEach((pattern, i) => {
        if (containsSensitiveData(pattern)) {
            violations.push(`trigger.filePatterns[${i}]`);
        }
    });
    // Check action payload reason fields
    const payload = learning.action.payload;
    if ("reason" in payload && typeof payload.reason === "string" && containsSensitiveData(payload.reason)) {
        violations.push("action.payload.reason");
    }
    if ("message" in payload && typeof payload.message === "string" && containsSensitiveData(payload.message)) {
        violations.push("action.payload.message");
    }
    if ("filePath" in payload && typeof payload.filePath === "string" && containsSensitiveData(payload.filePath)) {
        violations.push("action.payload.filePath");
    }
    // Check tags
    learning.tags?.forEach((tag, i) => {
        if (containsSensitiveData(tag)) {
            violations.push(`tags[${i}]`);
        }
    });
    return violations;
}
/**
 * Safe learning creation with validation
 * Throws if learning contains sensitive data
 */
export function createLearning(input, idGenerator) {
    // Validate input schema
    const parsed = LearningInputSchema.parse(input);
    // Check for sensitive data
    const violations = validateLearningForSensitiveData(parsed);
    if (violations.length > 0) {
        throw new Error(`Learning contains sensitive data in: ${violations.join(", ")}`);
    }
    // Create full learning
    return {
        ...parsed,
        id: idGenerator(),
        created: Date.now(),
        usageCount: 0,
        archived: parsed.archived ?? false,
    };
}
// =============================================================================
// LEARNING STORAGE SCHEMA (Phase 1 - Store Contract)
// =============================================================================
/**
 * LearningTier - storage tier classification for loading strategy
 * - hot: Always loaded (~10-15 entries, critical patterns)
 * - warm: Loaded based on intent/domain match (~20-30 per domain)
 * - cold: Query-only, never auto-loaded (archived learnings)
 */
export const LearningTierSchema = z.enum(["hot", "warm", "cold"]);
/**
 * LearningPriority - priority for tier promotion decisions
 */
export const LearningPrioritySchema = z.enum(["critical", "high", "medium", "low"]);
/**
 * LearningStorageType - extended learning types for storage layer
 * Includes all types from LearningTypeSchema plus storage-specific and legacy types
 */
export const LearningStorageTypeSchema = z.enum([
    "pattern",
    "pitfall",
    "pit", // Legacy alias for pitfall
    "architecture",
    "performance",
    "efficiency",
    "discovery",
    "workflow",
    "best-practice", // Legacy type
]);
/**
 * LearningStorageSchema - validates what stores actually return
 *
 * This is the Phase 1 store contract. It guards the boundary between
 * Intelligence and its backing stores (JSONL on disk).
 *
 * This schema is permanent - JSONL on disk is the simple format.
 * The transformation to rich LearningSchema happens in context/get.
 */
export const LearningStorageSchema = z.object({
    id: z.string().min(1).optional(), // Optional in older JSONL records - generated on read if missing
    type: LearningStorageTypeSchema,
    trigger: z.union([z.string(), z.array(z.string())]),
    context: z.string().optional(),
    problem: z.string().optional(),
    solution: z.string().optional(), // Optional in JSONL storage - some learnings only have action
    action: z.string(),
    related: z.array(z.string()).optional(),
    source: z.string(),
    timestamp: z.union([z.string(), z.number()]).describe("ISO 8601 string or epoch number from storage"),
    // Tiering metadata (optional)
    tier: LearningTierSchema.optional(),
    domain: z.string().optional(),
    priority: LearningPrioritySchema.optional(),
    keywords: z.array(z.string()).optional(),
    // Usage tracking (optional)
    accessCount: z.number().int().nonnegative().optional(),
    lastAccessed: z.string().optional(),
    relevanceScore: z.number().min(0).max(1).optional(),
    appliedDate: z.string().optional(),
});
// =============================================================================
// KNOWLEDGE CHUNK SCHEMA
// =============================================================================
/**
 * Source types for knowledge chunks
 */
export const ChunkSourceTypeSchema = z.enum(["learning", "adr", "pattern", "violation"]);
/**
 * Status of a knowledge chunk
 */
export const ChunkStatusSchema = z.enum(["active", "deprecated", "superseded"]);
/**
 * Knowledge chunk - a unit of captured insight stored in KnowledgeStore
 * Maps directly from packages/intelligence/src/knowledge/store.ts Chunk interface
 */
export const ChunkSchema = z.object({
    id: z.string().describe("Unique chunk identifier"),
    source_type: ChunkSourceTypeSchema.describe("Type of source this chunk came from"),
    source_id: z.string().describe("ID of the source record"),
    chunk_text: z.string().describe("The actual content text"),
    context_text: z.string().optional().describe("Optional context surrounding the chunk"),
    authority: z.number().min(0).max(1).describe("Authority score (0-1)"),
    status: ChunkStatusSchema.describe("Current status of the chunk"),
    created_at: z.string().describe("ISO 8601 creation timestamp"),
    updated_at: z.string().describe("ISO 8601 update timestamp"),
    metadata: z.record(z.unknown()).optional().describe("Optional JSON metadata"),
});
/**
 * Outcome types for confidence feedback loop
 */
export const OutcomeTypeSchema = z.enum(["accepted", "ignored", "test_pass", "test_fail", "violation_prevented"]);
/**
 * Outcome record for tracking chunk effectiveness
 */
export const OutcomeSchema = z.object({
    id: z.string(),
    chunk_id: z.string(),
    outcome_type: OutcomeTypeSchema,
    context: z.record(z.unknown()).optional(),
    created_at: z.string(),
});
// =============================================================================
// API SCHEMA FOR context/get (Phase 2 - Format Elevation)
// =============================================================================
/**
 * LearningApiSchema - the format returned by context/get for LLM consumption
 *
 * This is a normalized, LLM-friendly format that sits between:
 * - LearningStorageSchema (storage format, flexible, union types)
 * - LearningSchema (full schema with complex discriminated union actions)
 *
 * The elevation transform converts storage format to API format.
 */
export const LearningApiSchema = z.object({
    id: z.string().min(1).describe("Unique identifier"),
    type: LearningTypeSchema.describe("Categorical classification"),
    trigger: z.string().describe("Normalized trigger condition"),
    action: z.string().describe("Action to take (human-readable)"),
    confidence: z.number().min(0).max(1).describe("Confidence score (0.0-1.0)"),
    created: z.number().int().positive().describe("Creation timestamp (ms since epoch)"),
    source: z.string().describe("Where this learning originated"),
    tags: z.array(z.string()).default([]).describe("Searchable tags"),
    usageCount: z.number().int().nonnegative().default(0).describe("Times applied"),
});
/**
 * Elevate LearningStorage to LearningApi format
 *
 * This is the format elevation that happens in context/get assembly.
 * It normalizes storage format (flexible, union types) to API format
 * (deterministic, LLM-friendly).
 *
 * @param storage - Learning from storage (JSONL, SQLite, Hot tier)
 * @param options - Optional overrides for confidence computation
 */
/**
 * Normalize learning storage type to canonical API type.
 * Uses exhaustive checking to ensure all types are handled.
 */
function normalizeLearningType(type) {
    // Map all storage types (including legacy aliases) to canonical types
    switch (type) {
        case "pattern":
            return "pattern";
        case "pitfall":
        case "pit": // Legacy alias
            return "pitfall";
        case "efficiency":
        case "performance": // Legacy alias
            return "efficiency";
        case "workflow":
        case "best-practice": // Legacy alias
            return "workflow";
        case "discovery":
            return "discovery";
        case "architecture":
            return "pattern"; // Architecture patterns map to pattern
        default: {
            // Exhaustive check - TypeScript will error if any LearningStorageType is unhandled
            const _exhaustive = type;
            return "pattern"; // Safe fallback
        }
    }
}
export function elevateLearningToApi(storage, options) {
    // Generate ID if missing (older JSONL records)
    const id = storage.id ?? `learning-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
    // Normalize type with exhaustive checking
    const normalizedType = normalizeLearningType(storage.type);
    // Normalize trigger: array to comma-separated string
    const trigger = Array.isArray(storage.trigger) ? storage.trigger.join(", ") : storage.trigger;
    // Normalize timestamp: string or number to epoch ms
    let created;
    if (typeof storage.timestamp === "string") {
        const parsed = new Date(storage.timestamp);
        created = Number.isNaN(parsed.getTime()) ? Date.now() : parsed.getTime();
    }
    else {
        created = storage.timestamp;
    }
    // Compute confidence: use relevanceScore if present, otherwise derive
    const confidence = storage.relevanceScore ??
        (options?.relevanceBoost ?? 0.7) * (storage.accessCount ? Math.min(1, storage.accessCount / 10) : 0.5);
    return {
        id,
        type: normalizedType,
        trigger,
        action: storage.action,
        confidence: Math.round(confidence * 1000) / 1000, // Round to 3 decimals
        created,
        source: storage.source,
        tags: storage.keywords ?? [],
        usageCount: storage.accessCount ?? 0,
    };
}
/**
 * Schema transformation pipeline: Storage → API
 * Uses Zod transform for validation + transformation in one step.
 */
export const LearningStorageToApiSchema = LearningStorageSchema.transform((storage) => elevateLearningToApi(storage)).pipe(LearningApiSchema);
/**
 * Elevate array of learnings with deduplication
 *
 * Deduplication strategy:
 * 1. Same trigger+action = same learning (regardless of source)
 * 2. Keep highest confidence among duplicates
 * 3. Merge usage counts
 *
 * @param learnings - Array of storage-format learnings
 * @param maxResults - Maximum results to return (default 10)
 */
export function elevateAndDeduplicateLearnings(learnings, maxResults = 10) {
    const elevated = learnings.map((l) => elevateLearningToApi(l));
    // Deduplicate by trigger+action key
    const byKey = new Map();
    for (const learning of elevated) {
        const key = `${learning.trigger} → ${learning.action}`;
        const existing = byKey.get(key);
        if (!existing) {
            byKey.set(key, learning);
        }
        else {
            // Merge: keep higher confidence, sum usage counts
            byKey.set(key, {
                ...existing,
                confidence: Math.max(existing.confidence, learning.confidence),
                usageCount: existing.usageCount + learning.usageCount,
            });
        }
    }
    // Sort by confidence descending, limit results
    return Array.from(byKey.values())
        .sort((a, b) => b.confidence - a.confidence)
        .slice(0, maxResults);
}
// =============================================================================
// SCORING UTILITIES
// =============================================================================
/**
 * Calculate recency decay factor (0.5-1.0)
 * Newer learnings get higher scores
 * @param lastUsed - Last usage timestamp (ms)
 * @param maxAgeDays - Age at which decay reaches minimum (default 90 days)
 */
export function calculateRecencyDecay(lastUsed, maxAgeDays = 90) {
    if (!lastUsed) {
        return 0.5; // Never used = minimum multiplier
    }
    const ageMs = Date.now() - lastUsed;
    const ageDays = ageMs / (1000 * 60 * 60 * 24);
    const decay = 1 - (ageDays / maxAgeDays) * 0.5;
    return Math.max(0.5, Math.min(1, decay));
}
/**
 * Calculate learning score for ranking
 * Simple formula: confidence × recency_decay
 */
export function calculateLearningScore(learning) {
    const recencyDecay = calculateRecencyDecay(learning.lastUsed);
    return learning.confidence * recencyDecay;
}
/**
 * Calculate learning API score for ranking
 * Uses confidence and usage count
 */
export function calculateLearningApiScore(learning) {
    const recencyDecay = calculateRecencyDecay(learning.created);
    const usageBoost = Math.min(0.2, learning.usageCount * 0.02); // Up to +0.2 for heavy use
    return Math.min(1, learning.confidence * recencyDecay + usageBoost);
}
