// ESM imports fixed for Node.js v22+
/**
 * Sync Parameter Schemas
 *
 * All sync-related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/sync
 */
import { z } from "zod";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Sync status parameters
 */
export const SyncStatusParams = WorkspaceBase;
/**
 * Sync force parameters
 */
export const SyncForceParams = WorkspaceBase;
/**
 * Sync stop parameters
 */
export const SyncStopParams = WorkspaceBase;
/**
 * Sync start parameters
 */
export const SyncStartParams = WorkspaceBase.extend({
    /** Optional auth token for platform sync */
    authToken: z.string().optional(),
});
/**
 * Sync queue parameters
 */
export const SyncQueueParams = WorkspaceBase;
// =============================================================================
// Sync Result Schemas (VALID-T Batch 2)
// =============================================================================
export const SyncPushResult = z.object({
    success: z.boolean(),
    queued: z.boolean(),
});
export const SyncStatusResult = z.object({
    running: z.boolean(),
    lastSync: z.number().nullable(),
    pendingItems: z.number().int().nonnegative(),
    status: z.string(),
    queueDepth: z.number().int().nonnegative(),
});
/** sync/force and sync/trigger — triggers flush then sync worker */
export const SyncForceResult = z.object({
    triggered: z.boolean(),
    flushed: z.number().int().nonnegative(),
    remaining: z.number().int().nonnegative(),
    error: z.string().optional(),
});
export const SyncStopResult = z.object({
    stopped: z.boolean(),
});
export const SyncStartResult = z.object({
    started: z.boolean(),
    error: z.string().optional(),
});
export const SyncQueueResult = z.object({
    items: z.array(z.unknown()),
    total: z.number().int().nonnegative(),
});
