// ESM imports fixed for Node.js v22+
/**
 * Memory Hub Parameter Schemas
 *
 * Memory hub related request parameters.
 *
 * @module @vreko/contracts/local-service/schemas/memory
 */
import { z } from "zod";
import { MemoryEntryType } from "./primitives.js";
import { WorkspaceBase } from "./workspace-base.js";
/**
 * Memory store parameters
 */
export const MemoryStoreParams = WorkspaceBase.extend({
    /** Entry type */
    type: MemoryEntryType,
    /** Entry data */
    data: z.record(z.unknown()),
    /** TTL in days (0 = permanent) */
    ttlDays: z.number().int().min(0).default(0),
});
/**
 * Memory retrieve parameters
 */
export const MemoryRetrieveParams = WorkspaceBase.extend({
    /** Entry IDs to retrieve */
    ids: z.array(z.string().min(1)).min(1),
});
/**
 * Memory search parameters
 */
export const MemorySearchParams = WorkspaceBase.extend({
    /** Filter by type */
    type: MemoryEntryType.optional(),
    /** Keywords to match */
    keywords: z.array(z.string()).optional(),
    /** Minimum relevance score (0-1) */
    minRelevance: z.number().min(0).max(1).default(0.3),
    /** Maximum results */
    limit: z.number().int().min(1).max(100).default(50),
    /** Created after timestamp */
    since: z.number().optional(),
});
/**
 * Memory stats parameters
 */
export const MemoryStatsParams = WorkspaceBase;
/**
 * Memory compact parameters
 */
export const MemoryCompactParams = WorkspaceBase.extend({
    /** Preview only (don't modify) */
    dryRun: z.boolean().default(false),
});
// =============================================================================
// Memory Result Schemas (VALID-T Batch 4)
// =============================================================================
export const MemoryStoreResult = z.object({
    id: z.string(),
    stored: z.boolean(),
});
export const MemoryCompactResult = z.object({
    originalEntries: z.number().int().nonnegative(),
    keptEntries: z.number().int().nonnegative(),
    removedEntries: z.number().int().nonnegative(),
    savedBytes: z.number().nonnegative(),
});
