import { z } from "zod";
/**
 * Deterministic boot profile selection for vrekod startup.
 * Selected by reading local state  -  no heuristics.
 */
export const BootProfile = z.enum(["VIRGIN", "NEW_WORKSPACE", "COLD_RETURN", "WARM_RETURN", "HOT_RECONNECT"]);
export const BootProfileSelection = z.object({
    profile: BootProfile,
    workspaceId: z.string().optional(),
    lastSessionAge: z.number().nonnegative().optional(),
    integrityErrors: z.number().nonnegative().optional(),
    cleanShutdown: z.boolean().optional(),
});
export const CleanShutdownFlag = z.object({
    cleanShutdown: z.literal(true),
    timestamp: z.string().datetime(),
});
